-- ════════════════════════════════════════════════════════════════════════════════════════════════
-- 0053 · PHASE 11-D — the release predicate becomes lifecycle-aware (one signature, one authority)
-- ════════════════════════════════════════════════════════════════════════════════════════════════
--
-- ★ WHAT THIS PHASE CONNECTS, AND THE ONLY THING IT CONNECTS:
--
--       authoritative estate lifecycle state  (estate_lifecycle, read via estate_lifecycle_state)
--               ↓
--       public.release_condition_satisfied(condition, approved_at, policy, lifecycle_state)
--               ↓
--       existing owner-authored death-conditioned grants may become live
--
-- `after_verified_death` becomes satisfiable — under the `standard` policy only, and only while the
-- estate's authoritative lifecycle is `death_verified`. Nothing else moves:
--
--   · NO grant is created, widened, re-tiered or re-approved. Activation is EVALUATIVE — the same
--     stored row, the same ceiling, the same membership requirements, one predicate answering
--     differently because the lifecycle fact it now consumes has changed.
--   · `legacy_immediate_only` is PRESERVED EXACTLY: the asset-value surfaces still honour
--     `immediately` alone. A death-conditioned asset grant stays dormant on those surfaces.
--     Policy unification remains a deferred product decision (R12), not a side effect.
--   · `after_verified_incapacity` stays dormant (no incapacity workflow exists — R6).
--   · `after_verified_death_or_incapacity` (legacy fused rows) stays dormant and unreinterpreted (R7).
--   · claim approval, evidence receipt, evidence review and attained verification levels satisfy
--     nothing — only the lifecycle record does, and only its one audited writer can move it.
--   · No `released` estate state exists; the 0052 CHECK still cannot store one.
--
-- ★ THE DDL HERE IS ONE DROP. The widened predicate itself lives in
-- `db/functions/release_conditions.sql` (the canonical module) and arrives with the bundle; what a
-- migration must own is the removal of the LIFECYCLE-BLIND overload. `create or replace` cannot
-- replace across a signature change — it would leave both, and Postgres overload resolution would
-- quietly keep serving the 3-argument version to any consumer that was not rewired. A consumer that
-- bypasses the widening must fail LOUDLY at first call, not keep getting yesterday's answer.
--
-- DEPLOYMENT STATE NOTE: the 11-B/11-C bundles are source-merged but not yet pasted, so no deployed
-- database carries the 3-argument predicate; there this drop is a documented no-op. The database it
-- is load-bearing for is any that applied the 11-B artifacts (the SQL harness, a dev paste).
--
-- IDEMPOTENT. Safe to re-apply: `drop function if exists`, and the self-check raises rather than
-- silently no-ops.
--
-- APPLY ORDER: inside `release_conditions_bundle.sql`, after 0051/0052 and immediately before the
-- canonical module that creates the 4-argument predicate. Standing rule unchanged: that bundle is
-- pasted FIRST, before any other bundle re-application.

\set ON_ERROR_STOP on

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- 1 · REMOVE the lifecycle-blind overload, so exactly one authority can exist.
-- ────────────────────────────────────────────────────────────────────────────────────────────────
drop function if exists public.release_condition_satisfied(text, timestamptz, text);

-- ★ PROVE THE REMOVAL TOOK. A drop that silently missed (a renamed schema, an altered signature)
-- would leave two authorities answering the same question, and the un-rewired consumer would keep
-- binding to the blind one — green everywhere, wrong at the first verified death.
do $$
begin
  if to_regprocedure('public.release_condition_satisfied(text, timestamptz, text)') is not null then
    raise exception '0053 FAILED: the 3-argument (lifecycle-blind) release_condition_satisfied still '
      'exists after the drop — two release authorities would coexist and overload resolution would '
      'quietly serve the blind one to any consumer that was not rewired';
  end if;
  raise notice '0053 · lifecycle-blind release predicate removed (the 4-argument authority in '
    'release_conditions.sql is now the only satisfiable spelling)';
end $$;


-- ==== db/migrations/0054_20260812_challenge_window_release_seam.sql ===============================
-- ════════════════════════════════════════════════════════════════════════════════════════════════
-- 0054 · PHASE 11-E — the challenge window: the safety seam between death_verified and released
-- ════════════════════════════════════════════════════════════════════════════════════════════════
--
-- ★ WHAT THIS PHASE INSERTS, AND WHY IT EXISTS. 11-D let `after_verified_death` satisfy at
-- `death_verified`. That connected verification directly to irreversible disclosure — and disclosure
-- cannot be undone (R15: revoking future access is possible; undoing disclosure is not). 11-E
-- inserts the missing safety states between them:
--
--     active → death_verification_pending → death_verified
--            → challenge_window            (verification accepted; release deliberately waiting;
--                                           the owner has been notified and can object)
--            → released                    (the ONLY lifecycle at which owner-authored
--                                           death-conditioned grants may evaluate as satisfied)
--     any pre-released death-process state
--            → challenge_halted            (the authenticated owner objected; terminal in 11-E)
--
-- The predicate change rides in `release_conditions.sql`: `after_verified_death` is FALSE at
-- death_verified, FALSE throughout challenge_window, FALSE at challenge_halted, TRUE only at
-- released. So this migration making `released` STORABLE widens no disclosure: the only writer is
-- `release_estate` (client-revoked, no reachable door in 11-E), behind an elapsed, configured,
-- owner-notified, unchallenged window.
--
-- ★ THE WINDOW DURATION IS CONFIGURATION, NOT A GUESS. `release_safety_policy` ships EMPTY: no
-- default duration is seeded, because the duration is a product decision this phase does not own.
-- Fail-closed direction: an estate can always ENTER the challenge window (the owner-safety clock
-- and notice), but with no configured duration the window NEVER ELAPSES and release refuses with
-- `release_window_not_configured`. The duration is re-read LIVE at release time (the H2 precedent:
-- a policy tightened mid-window tightens the window) — never stamped at entry.
--
-- ★ THE OWNER CHALLENGE IS CHEAPER THAN THE CLAIM (R13) AND WINS TIES (R14). No evidence, no
-- review, no waiting period, no designation — one authenticated owner action. The tiebreak is
-- structural: release requires the window STRICTLY elapsed (`now() > notified_at + duration`), so
-- at the exact boundary instant release refuses while challenge still succeeds; both transitions
-- serialize on the lifecycle row lock, and nothing transitions out of challenge_halted.
--
-- IDEMPOTENT. Safe to re-apply. APPLY ORDER: after 0052/0053, inside the bundles that carry it.

\set ON_ERROR_STOP on

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- 1 · WIDEN the lifecycle vocabulary to the six-state safety machine. Additive only.
-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- The constraint name is resolved from the catalog, not guessed (the 0051 lesson).
do $$
declare
  v_name text;
begin
  for v_name in
    select con.conname
      from pg_constraint con
      join pg_class rel on rel.oid = con.conrelid
      join pg_namespace nsp on nsp.oid = rel.relnamespace
     where nsp.nspname = 'public'
       and rel.relname = 'estate_lifecycle'
       and con.contype = 'c'
       and pg_get_constraintdef(con.oid) ilike '%state%'
  loop
    execute format('alter table public.estate_lifecycle drop constraint %I', v_name);
  end loop;

  alter table public.estate_lifecycle
    add constraint estate_lifecycle_state_check
    check (state in (
      'active',
      'death_verification_pending',
      'death_verified',
      -- Phase 11-E: the safety seam. Storable here; REACHABLE only through the closed transition
      -- map in apply_estate_lifecycle_transition, and 'released' only through release_estate.
      'challenge_window',
      'challenge_halted',
      'released'
    ));
end $$;

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- 2 · THE SAFETY FACTS live on the lifecycle row: when the owner was notified, when the window
--     opened, when it was halted or released, and WHICH notification row is the safety notice.
--     Facts, never authority — release re-derives everything live.
-- ────────────────────────────────────────────────────────────────────────────────────────────────
alter table public.estate_lifecycle add column if not exists owner_notified_at            timestamptz;
alter table public.estate_lifecycle add column if not exists challenge_window_started_at  timestamptz;
alter table public.estate_lifecycle add column if not exists halted_at                    timestamptz;
alter table public.estate_lifecycle add column if not exists released_at                  timestamptz;
alter table public.estate_lifecycle add column if not exists safety_notification_id       uuid;

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- 3 · A HALTED CASE IS ITS OWN STATUS. The owner challenge halts any open case; 'cancelled' means
--     the initiator withdrew and reusing it would erase the difference between "the claimant
--     changed their mind" and "the owner said they are alive" — facts with different forensics.
-- ────────────────────────────────────────────────────────────────────────────────────────────────
do $$
declare
  v_name text;
begin
  for v_name in
    select con.conname
      from pg_constraint con
      join pg_class rel on rel.oid = con.conrelid
      join pg_namespace nsp on nsp.oid = rel.relnamespace
     where nsp.nspname = 'public'
       and rel.relname = 'death_verification_cases'
       and con.contype = 'c'
       and pg_get_constraintdef(con.oid) ilike '%status%'
       and pg_get_constraintdef(con.oid) not ilike '%event_type%'
       and pg_get_constraintdef(con.oid) not ilike '%review_status%'
       and pg_get_constraintdef(con.oid) not ilike '%initiator_capacity%'
  loop
    execute format('alter table public.death_verification_cases drop constraint %I', v_name);
  end loop;

  alter table public.death_verification_cases
    add constraint death_verification_cases_status_check
    check (status in ('open', 'verified', 'rejected', 'cancelled',
                      -- Phase 11-E: set only by the owner-challenge routine.
                      'halted'));
end $$;

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- 4 · THE WINDOW-DURATION CONFIGURATION — one row, definer-only, DELIBERATELY UNSEEDED.
-- ────────────────────────────────────────────────────────────────────────────────────────────────
create table if not exists public.release_safety_policy (
  -- Single-row table: the PK admits exactly `true`.
  id               boolean     primary key default true check (id),
  challenge_window interval    not null,
  updated_at       timestamptz not null default now()
);

alter table public.release_safety_policy enable row level security;
-- ZERO grants, ZERO policies — reachable only through the DEFINER reader. No seed row: the
-- duration is a product/operator decision recorded by an explicit, reviewed INSERT, and until it
-- exists the release window cannot elapse anywhere.

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- 5 · PROVE THE SEAM TOOK, IN THE MIGRATION ITSELF (both directions, the 0051/0052 discipline).
-- ────────────────────────────────────────────────────────────────────────────────────────────────
do $$
declare
  v_def text;
begin
  select pg_get_constraintdef(con.oid) into v_def
    from pg_constraint con
    join pg_class rel on rel.oid = con.conrelid
    join pg_namespace nsp on nsp.oid = rel.relnamespace
   where nsp.nspname = 'public' and rel.relname = 'estate_lifecycle'
     and con.contype = 'c' and pg_get_constraintdef(con.oid) ilike '%state%';
  if v_def is null then
    raise exception '0054 FAILED: estate_lifecycle has no state CHECK after the widening';
  end if;
  if position('challenge_window' in v_def) = 0
     or position('challenge_halted' in v_def) = 0
     or position('released' in v_def) = 0 then
    raise exception '0054 FAILED: the safety vocabulary is incomplete: %', v_def;
  end if;
  if (select count(*) from regexp_matches(v_def, '''[a-z_]+''', 'g')) <> 6 then
    raise exception '0054 FAILED: the lifecycle vocabulary is not exactly six states: %', v_def;
  end if;
  -- 'frozen' and other invented states must still be unrepresentable.
  if position('frozen' in v_def) > 0 then
    raise exception '0054 FAILED: an unapproved lifecycle state is storable: %', v_def;
  end if;

  select pg_get_constraintdef(con.oid) into v_def
    from pg_constraint con
    join pg_class rel on rel.oid = con.conrelid
    join pg_namespace nsp on nsp.oid = rel.relnamespace
   where nsp.nspname = 'public' and rel.relname = 'death_verification_cases'
     and con.conname = 'death_verification_cases_status_check';
  if v_def is null or position('halted' in v_def) = 0 then
    raise exception '0054 FAILED: the case status vocabulary did not gain ''halted'': %',
      coalesce(v_def, '<absent>');
  end if;

  -- The policy table is definer-only and EMPTY: a seeded duration would be a product decision
  -- taken by a migration.
  if exists (
    select 1 from information_schema.role_table_grants
     where table_schema = 'public' and table_name = 'release_safety_policy'
       and grantee in ('anon', 'authenticated')
  ) then
    raise exception '0054 FAILED: a client role holds a grant on release_safety_policy';
  end if;
  if (select count(*) from public.release_safety_policy) <> 0 then
    -- On RE-application to a database whose operator later configured the window, a row is
    -- legitimate — the check refuses only a duration arriving in the SAME transaction that
    -- created the table (i.e. seeded by migration).
    if (select min(updated_at) from public.release_safety_policy) >= transaction_timestamp() then
      raise exception '0054 FAILED: release_safety_policy was seeded by this migration — the '
        'window duration is a product decision, not a default';
    end if;
  end if;

  raise notice '0054 · challenge-window seam in place (6 lifecycle states; halted case status; '
    'safety facts columns; duration configuration table EMPTY and definer-only)';
end $$;


-- ==== db/functions/release_conditions.sql =========================================================
-- ════════════════════════════════════════════════════════════════════════════════════════════════
-- THE CANONICAL RELEASE-CONDITION AUTHORITY  ·  Phase 11-B, lifecycle-aware since Phase 11-D
-- ════════════════════════════════════════════════════════════════════════════════════════════════
--
-- ★ WHY THIS FILE EXISTS. Before Phase 11-B the rule "is this grant's release condition satisfied?"
-- was written out SEVEN times in FIVE routines, and the seven copies gave TWO different answers:
--
--     can_access_document          immediately + the two approval conditions once approved
--     inventory_disclosure_tier    same
--     notification_grant_is_live   same
--     asset_grant_tier             immediately ONLY
--     list_estate_assets           immediately ONLY
--     get_estate_net_worth  (×2)   immediately ONLY
--
-- Phase 11 connects a verified death to disclosure. The single most likely way to get that wrong is
-- not a missing check — it is activating a condition at four sites and forgetting the other three,
-- which is precisely the shape of the four role maps that drifted apart in Phase 9. So the predicate
-- moved HERE first (11-B), before any death wiring existed, and every consumer became a caller.
--
-- ════════════════════════════════════════════════════════════════════════════════════════════════
-- ★ WHAT THIS MODULE DECIDES, AND WHAT IT DELIBERATELY DOES NOT
-- ════════════════════════════════════════════════════════════════════════════════════════════════
--
-- It answers ONE question: given a release condition, the approval fact recorded beside it, and the
-- estate's authoritative lifecycle state, is that condition presently SATISFIED?
--
-- It does NOT decide who may receive a grant, compute a disclosure tier, manufacture a grant, verify
-- a death, approve a claim, or transition any lifecycle state. Callers keep every one of those. A
-- grant whose condition is satisfied still discloses nothing unless the SAME checks that have always
-- guarded it also pass: active status, the viewer's own grant row, the read-time ceiling clamp, the
-- hidden-tier refusal. Satisfaction is one conjunct, never a bypass.
--
-- ★ IT TAKES LIFECYCLE STATE AS AN ARGUMENT, AND READS NOTHING — THAT IS THE 11-D DESIGN.
--
-- 11-B deliberately gave this function no lifecycle argument, so that "no authorization path
-- consults the release seam" stayed structurally true while there was no verified event to consult.
-- 11-D is the phase that spends that guarantee, deliberately, in ONE file: the signature widens to
--
--     release_condition_satisfied(condition, approved_at, policy, lifecycle_state)
--
-- and every consumer resolves the lifecycle through `public.estate_lifecycle_state(estate)` — the
-- authoritative reader over `estate_lifecycle`, the record whose ONLY writer is the audited
-- transition routine. The predicate itself stays a PURE function of its arguments (immutable, no
-- table reads), for three reasons:
--
--   · a pure predicate can be truth-tabled exhaustively against a written specification, which is
--     how the SQL suite proves it (every condition × approval × policy × lifecycle, enumerated);
--   · a predicate that resolved estate → lifecycle itself would be a client-reachable death-status
--     oracle for arbitrary estate ids (it is EXECUTEable by `authenticated`; the reader is not);
--   · the lifecycle READ stays in SECURITY DEFINER consumers beside the grant lookup it scopes, so
--     the estate whose lifecycle is consulted is by construction the estate whose grant is evaluated.
--
-- What no consumer may do is compare the lifecycle locally ("if death_verified then …") — that is
-- release policy leaking back out of the centre, and `test/deathVerificationFoundation.test.ts`
-- pins that the reader appears outside the death module ONLY as this function's fourth argument.
--
-- ★ NOT `claim_packets.status`. NOT evidence rows. NOT attained verification levels. NOT the
-- label-only `estate_release_state()` claim projection. The lifecycle record is the one fact that
-- can satisfy a death condition, and it moves only through `apply_estate_lifecycle_transition`,
-- behind an admin decision that re-derives the required verification level LIVE (H2).
--
-- ════════════════════════════════════════════════════════════════════════════════════════════════
-- ★ TWO POLICIES, STILL — 11-D activates death under `standard` and PRESERVES the legacy clamp
-- ════════════════════════════════════════════════════════════════════════════════════════════════
--
-- `standard` (documents, the estate-documents category, estate inventory, notification speech):
-- gains the death arm. `after_verified_death` is satisfied exactly while the lifecycle is
-- `death_verified`.
--
-- `legacy_immediate_only` (account balances, institution names, total asset value, linked account
-- details): carried forward EXACTLY as written — `immediately` alone, lifecycle-indifferent. A
-- death-conditioned grant on an asset-value surface therefore stays dormant even at death_verified.
-- That asymmetry is deliberate and is pinned by test in both directions: unifying the policies
-- changes what a survivor sees on the asset surfaces, which is a product decision with its own row
-- inventory and migration price (R12), not a tidy-up. The divergence remains one `case` arm in one
-- file instead of seven scattered literals.
--
-- ════════════════════════════════════════════════════════════════════════════════════════════════
-- ★ FAIL-CLOSED IN EVERY ARGUMENT
-- ════════════════════════════════════════════════════════════════════════════════════════════════
--
-- An unknown condition is false. An unknown policy is false. An unknown or NULL lifecycle state is
-- false — for EVERY condition, including `immediately`: the authoritative reader can only produce
-- the three CHECK-constrained states, so an out-of-vocabulary lifecycle here means a consumer wired
-- something that is not the seam, and the answer to a miswired consumer is refusal, not tolerance.
-- NULL condition and NULL policy are false. There is no permissive default and no `else true`
-- anywhere below.
--
-- The `coalesce` is load-bearing rather than defensive tidiness: `null = 'immediately'` is NULL, not
-- false, and a boolean gate that returns NULL is not refused by `if not (…) then` — that branch
-- simply does not execute, and the caller carries on as though the check had passed. A three-valued
-- answer from a two-valued gate is how a fail-closed predicate fails open.

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- release_condition_satisfied(condition, approved_at, policy, lifecycle_state) — THE AUTHORITY
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- `p_policy` has NO DEFAULT, on purpose. A default would let a new consumer inherit the wider rule by
-- saying nothing, which is the exact failure mode — silent policy by omission — that the seven
-- scattered copies represented. `p_lifecycle_state` has no default for the same reason: a consumer
-- that says nothing about the lifecycle must not silently evaluate "as if active"; it must not
-- compile. (The 3-argument spelling is DROPPED by migration 0053, so an un-rewired caller fails
-- loudly at first call rather than binding to a lifecycle-blind overload.)
create or replace function public.release_condition_satisfied(
  p_release_condition text,
  p_approved_at       timestamptz,
  p_policy            text,
  p_lifecycle_state   text
)
 returns boolean
 language sql
 immutable
 set search_path to 'public'
as $function$
  select coalesce(
    -- ★ THE LIFECYCLE VALIDITY GATE COMES FIRST and refuses EVERYTHING on an out-of-vocabulary
    -- state. The set is the deployed CHECK's (0052 widened by 0054), spelled here because a pure
    -- function cannot read the catalog; `db/tests/release_condition_authorization.sql` enumerates
    -- the CHECK at run time and fails if the two vocabularies ever drift.
    p_lifecycle_state in ('active', 'death_verification_pending', 'death_verified',
                          'challenge_window', 'challenge_halted', 'released')
    and case p_policy
      -- Documents, the estate-documents category, estate inventory, and notification speech.
      -- `after_owner_approval` (owner-initiated) and `after_access_request_approval`
      -- (beneficiary-initiated) are the SAME gate — both mean "the owner approved this access",
      -- differing only by who asked.
      when 'standard' then
        p_release_condition = 'immediately'
        or (p_release_condition in ('after_owner_approval', 'after_access_request_approval')
            and p_approved_at is not null)
        -- ★ THE DEATH ARM — RE-POINTED IN PHASE 11-E (R7). 11-D satisfied this at death_verified;
        -- that connected an accepted verification DIRECTLY to irreversible disclosure, and 11-E
        -- inserts the safety seam: the condition is satisfied ONLY at `released`, which is
        -- reachable only through the challenge window — owner notified in the same transaction,
        -- configured duration strictly elapsed, no owner challenge. death_verified satisfies
        -- NOTHING; challenge_window satisfies NOTHING; challenge_halted satisfies NOTHING.
        -- Claim approval, evidence, and attained levels never appear here because they cannot
        -- move the lifecycle. Incapacity and the legacy fused value stay out of this arm
        -- entirely — dormant under every policy, every lifecycle (R8/R9).
        or (p_release_condition = 'after_verified_death'
            and p_lifecycle_state = 'released')

      -- The asset-value surfaces (account balances, institution names, total asset value, linked
      -- account details). Carried forward EXACTLY as written in 11-B, including their narrowness
      -- and their lifecycle-indifference: `immediately` alone, at every lifecycle state. This is a
      -- compatibility clamp with a standing ledger entry (R12), not a rule anyone designed — and
      -- 11-D deliberately does NOT spend that product decision.
      when 'legacy_immediate_only' then
        p_release_condition = 'immediately'

      -- Unknown policy -> refused. No `else true`, ever.
      else false
    end,
    false);
$function$;

comment on function public.release_condition_satisfied(text, timestamptz, text, text) is
  'THE canonical release-condition authority (Phase 11-B; lifecycle-aware since 11-D; safety-seamed '
  'in 11-E). Answers only "is this condition presently satisfied", never who may receive a grant, '
  'what tier they get, or whether anyone has died. PURE: the lifecycle arrives as an argument, '
  'resolved by SECURITY DEFINER consumers through public.estate_lifecycle_state — never from claim '
  'status, evidence, or attained levels. after_verified_death is satisfied only under the standard '
  'policy at RELEASED (R7) — death_verified, challenge_window and challenge_halted all satisfy '
  'nothing; incapacity, the legacy fused value, identity and claim conditions are dormant under '
  'every policy. Unknown condition, unknown policy, unknown lifecycle and NULL all refuse.';

revoke execute on function public.release_condition_satisfied(text, timestamptz, text, text) from public, anon;
grant  execute on function public.release_condition_satisfied(text, timestamptz, text, text) to authenticated;

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- release_condition_writable(condition) -> boolean   — THE WRITE-TIME VOCABULARY GATE
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ THE DEATH/INCAPACITY SPLIT LIVES HERE, AND IT IS A WRITE-SIDE RULE ONLY.
--
-- `after_verified_death_or_incapacity` fused two legally distinct events into one storable value.
-- Death and incapacity differ in who is alive to contest, what evidence exists, whether the owner's
-- own instructions still govern, and whether the change is reversible. A single condition cannot
-- carry both and mean anything.
--
-- The split is done WITHOUT touching stored rows:
--
--   · the table CHECK still ACCEPTS the fused value, so every existing row remains readable and no
--     migration has to guess what an owner meant when they chose it;
--   · this gate REFUSES it for new writes, so no further row can be created carrying the ambiguity;
--   · the satisfied-predicate above treats it as dormant — exactly as it was before — so a legacy
--     row is no more permissive than it was yesterday and no less.
--
-- ★ THE LEGACY VALUE IS NOT REINTERPRETED, AND 11-D DID NOT CHANGE THAT. Now that a verified death
-- can activate `after_verified_death`, the pull to "complete the migration" by mapping fused rows
-- onto the death condition is stronger than ever — and it is still a guess about owner intent that
-- silently makes a stored grant activate on an event the owner may never have chosen alone. Mapping
-- them to `after_verified_incapacity` is the same guess pointing the other way. Both are product
-- decisions about somebody else's estate. An explicit unsatisfiable legacy state costs a
-- re-authoring; a wrong guess costs a disclosure that cannot be undone.
--
-- ★ WRITABLE IS NOT LIVE. `after_verified_death` being writable (11-B) and satisfiable (11-D) are
-- separate facts; `after_verified_incapacity` remains writable and satisfied by NOTHING — nothing
-- verifies an incapacity, and the predicate admits it under no policy. This gate widens what an
-- owner may EXPRESS, never what anybody may SEE.
create or replace function public.release_condition_writable(p_release_condition text)
 returns boolean
 language sql
 immutable
 set search_path to 'public'
as $function$
  select coalesce(p_release_condition in (
    'never',
    'immediately',
    'after_owner_approval',
    'after_identity_verification',
    'after_access_request_approval',
    -- Phase 11-B: the split. Storable and expressible; death satisfiable only since 11-D and only
    -- at death_verified under the standard policy; incapacity satisfied by nothing.
    'after_verified_death',
    'after_verified_incapacity',
    'after_claim_case_approval'
    -- 'after_verified_death_or_incapacity' is DELIBERATELY ABSENT — readable, never writable again.
  ), false);
$function$;

comment on function public.release_condition_writable(text) is
  'Write-time vocabulary gate for access_grants.release_condition (Phase 11-B). Accepts the split '
  'after_verified_death / after_verified_incapacity and REFUSES the deprecated fused '
  'after_verified_death_or_incapacity, which remains legal in the CHECK so stored rows stay readable '
  'and unreinterpreted. Writable is not live: incapacity is satisfied by no policy, and death only '
  'by the authoritative death_verified lifecycle under the standard policy (11-D).';

revoke execute on function public.release_condition_writable(text) from public, anon;
grant  execute on function public.release_condition_writable(text) to authenticated;


-- ==== db/functions/estate_lifecycle_state.sql =====================================================
-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- estate_lifecycle_state(p_estate) → text            [INTERNAL — the authoritative lifecycle read]
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ EXTRACTED FROM `death_verification.sql` IN PHASE 11-D, because the seam changed sides. In 11-C
-- this reader existed for the death-verification routines and was consulted by nobody else — that
-- absence was the firewall. In 11-D the canonical release predicate consumes lifecycle state as an
-- argument, so every disclosure evaluator resolves it at read time. The reader therefore ships in
-- `release_conditions_bundle.sql` (the FIRST artifact an operator pastes), so that no paste order
-- ever leaves a consumer referencing a reader that does not exist yet. The death-verification
-- bundle also carries it (idempotent re-create), keeping that artifact single-paste runnable.
--
-- ★ ABSENT ROW = 'active'. An estate that has never seen a death-verification case has no row in
-- `estate_lifecycle`, and this reader answers the base state. The empty table is a correct table.
--
-- ★ THE CLOSED SET IS THE TABLE'S, NOT THIS FUNCTION'S. The CHECK on `estate_lifecycle.state`
-- (migration 0052) admits exactly 'active' / 'death_verification_pending' / 'death_verified', and
-- the canonical predicate REFUSES any lifecycle value outside that set — so a state this reader
-- could never produce fails closed at the predicate rather than being interpreted.
--
-- ★ NO CLIENT MAY EXECUTE THIS. A client that can map estate → lifecycle state has been handed a
-- death-status oracle for arbitrary estates. Its callers are SECURITY DEFINER routines (the
-- death-verification module and the disclosure evaluators) and the SQL suite. The disclosure rule
-- for consumers is pinned by `test/deathVerificationFoundation.test.ts`: outside the death module,
-- this function may appear ONLY as the lifecycle argument of `public.release_condition_satisfied` —
-- never as the subject of a local comparison, which would be release policy leaking out of the
-- canonical predicate one `if` at a time.
create or replace function public.estate_lifecycle_state(p_estate uuid)
 returns text
 language sql
 security definer
 stable
 set search_path to 'public'
as $function$
  select coalesce(
    (select l.state from public.estate_lifecycle l where l.estate_id = p_estate),
    'active');
$function$;
revoke execute on function public.estate_lifecycle_state(uuid) from public, anon, authenticated;

comment on function public.estate_lifecycle_state(uuid) is
  'THE authoritative estate lifecycle read (Phase 11-C, extracted 11-D). Absent row = active. '
  'INTERNAL: execute revoked from every client role — a client that can map estate to lifecycle '
  'state holds a death-status oracle. Consumed by the death-verification routines and, since 11-D, '
  'as the lifecycle argument to public.release_condition_satisfied inside disclosure evaluators. '
  'Never derived from claim_packets.status, evidence, or attained verification levels.';


-- ==== db/migrations/0048_20260810_estate_assets.sql ===============================================
-- db/migrations/0048_20260810_estate_assets.sql
--
-- PHASE 9 — the MANUAL estate asset inventory. An owner records what the estate actually consists of:
-- accounts, property, business interests, digital assets and physical valuables — without any
-- dependency on financial aggregation.
--
-- ★ WHY THIS IS A NEW TABLE AND NOT A COLUMN ON normalized_assets.
--   `normalized_assets` (0007) is AGGREGATOR-SHAPED and aggregator-OWNED:
--     * `connection_id` is NOT NULL and FKs to `connections`, so a manual asset has no legal row;
--     * a connection refresh performs DELETE + INSERT for the connection's rows, so anything manual
--       parked there would be destroyed by a Plaid sync — silently, and only for users who happen to
--       link an account.
--   Manual assets are therefore first-class in their own table, exactly as the product treats them.
--
-- ★ AAL2 POSTURE — OWNER-APPROVED RULING (Phase 9), AND IT LOOSENS NOTHING.
--   `list_estate_assets` keeps `require_aal2()` for aggregator-sourced exact values: UNCHANGED.
--   Cross-person disclosure keeps its gate: UNCHANGED (and no non-owner can read this table at all —
--   see the RLS note below). What is new is that an owner may read the values THEY THEMSELVES TYPED
--   at aal1, because re-proving identity to read back your own typing protects nothing, and the app
--   has no in-app TOTP enrollment flow, so the alternative was an enrollment wall in front of the
--   MVP's core feature.
--
-- ★ NON-OWNERS SEE NOTHING HERE, DELIBERATELY, AND THAT IS THE WHOLE PHASE-9 DISCLOSURE STORY FOR
--   MANUAL ASSETS. `access_grants` scopes a grant by an XOR of `document_id` / `category`; adding an
--   asset scope means altering that XOR and the write-time ceiling trigger keyed on `document_id` —
--   a change to the security-critical centre of the disclosure model. That is NOT smuggled into an
--   inventory slice. Manual assets are owner-only until per-asset grants are designed on their own
--   merits. Default-deny is the safe direction, and it is enforced structurally by RLS.
--
-- ★ DELETION — OWNER-APPROVED RULING (Phase 9): SOFT delete (archive) with restore. Documents keep
--   their locked HARD-delete design because their irreversibility is justified by a storage-byte
--   purge; a manual asset has no bytes of its own, so an accidental deletion during bulk inventory
--   entry is recoverable. Archiving an asset detaches no document and purges nothing.
--
-- Idempotent; safe to re-run.

begin;

-- =============================================================================================
-- 1 · estate_asset_category — the COARSE server-authoritative vocabulary
-- =============================================================================================
-- Born clean, exactly like `document_subtype` (0036): RLS on, NO client grants. The read path is
-- get_estate_asset_taxonomy(). A client union here would be a second source of truth that drifts the
-- moment a category is added — the taxonomy rule this codebase learned from `subtype: 'other'`.
create table if not exists public.estate_asset_category (
  value        text        primary key,
  display_name text        not null,
  description  text,
  sort_order   int         not null default 0,
  icon_key     text,
  -- PRESENTATION metadata only, never authorization: it tells the client which optional fields are
  -- worth offering (a location hint for a ring, an institution for a brokerage account).
  is_physical  boolean     not null default false,
  is_active    boolean     not null default true,
  created_at   timestamptz not null default now()
);
alter table public.estate_asset_category enable row level security;

-- =============================================================================================
-- 2 · estate_asset_subtype — the FINE vocabulary, parented to a category
-- =============================================================================================
-- Mirrors document_subtype → document_type: persist-both, so a client that does not recognise a new
-- subtype can still group by its parent category rather than losing the row.
create table if not exists public.estate_asset_subtype (
  subtype         text        primary key,
  parent_category text        not null references public.estate_asset_category(value),
  display_name    text        not null,
  description     text,
  sort_order      int         not null default 0,
  icon_key        text,
  is_active       boolean     not null default true,
  created_at      timestamptz not null default now()
);
create index if not exists estate_asset_subtype_parent_idx
  on public.estate_asset_subtype (parent_category);
alter table public.estate_asset_subtype enable row level security;

-- =============================================================================================
-- 3 · SEED — the nine categories from the product definition
-- =============================================================================================
insert into public.estate_asset_category (value, display_name, description, sort_order, icon_key, is_physical) values
  ('bankAccount',      'Bank or financial account', 'Chequing, savings, term deposits and similar cash holdings.', 1, 'financial', false),
  ('investment',       'Investment',                'Brokerage accounts and directly held securities.',            2, 'financial', false),
  ('retirement',       'Retirement or pension',     'Workplace pensions, personal retirement accounts, annuities.', 3, 'financial', false),
  ('insurance',        'Insurance',                 'Policies that pay out to the estate or to a named person.',   4, 'authority', false),
  ('realEstate',       'Real estate',               'Land and buildings, wherever they are held.',                  5, 'property',  false),
  ('businessInterest', 'Business interest',         'Ownership in a company, partnership or practice.',             6, 'authority', false),
  ('digitalAsset',     'Crypto or digital asset',   'Exchange accounts, self-custody wallets and digital property.', 7, 'financial', false),
  ('physicalValuable', 'Physical valuable',         'Items whose value is in the object itself.',                   8, 'property',  true),
  ('otherAsset',       'Other asset',               'Anything the other categories do not describe.',               9, 'document',  false)
on conflict (value) do update set
  display_name = excluded.display_name,
  description  = excluded.description,
  sort_order   = excluded.sort_order,
  icon_key     = excluded.icon_key,
  is_physical  = excluded.is_physical;

-- =============================================================================================
-- 4 · SEED — subtypes. `customAsset` is the GENERIC entry, the analogue of `customDocument`.
-- =============================================================================================
-- ★ THE GENERIC ENTRY EXISTS SO THE CLIENT NEVER HAS TO INVENT ONE. The Vault defect was a client
-- sending a value the catalog did not contain; a resolvable generic is what makes "I don't know what
-- this is" expressible IN the vocabulary instead of beside it.
insert into public.estate_asset_subtype (subtype, parent_category, display_name, sort_order) values
  ('chequingAccount',       'bankAccount',      'Chequing account',            1),
  ('savingsAccount',        'bankAccount',      'Savings account',             2),
  ('moneyMarketAccount',    'bankAccount',      'Money market account',        3),
  ('termDeposit',           'bankAccount',      'Term deposit or GIC/CD',      4),

  ('brokerageAccount',      'investment',       'Brokerage account',           1),
  ('directEquity',          'investment',       'Directly held shares',        2),
  ('bondHolding',           'investment',       'Bonds',                       3),
  ('fundHolding',           'investment',       'Mutual or index funds',       4),

  ('workplacePension',      'retirement',       'Workplace pension',           1),
  ('personalRetirement',    'retirement',       'Personal retirement account', 2),
  ('annuityContract',       'retirement',       'Annuity',                     3),

  ('lifeInsurance',         'insurance',        'Life insurance policy',       1),
  ('criticalIllnessCover',  'insurance',        'Critical illness cover',      2),
  ('longTermCareCover',     'insurance',        'Long-term care cover',        3),

  ('primaryResidence',      'realEstate',       'Primary residence',           1),
  ('secondaryProperty',     'realEstate',       'Second or holiday property',  2),
  ('rentalProperty',        'realEstate',       'Rental property',             3),
  ('landParcel',            'realEstate',       'Land',                        4),

  ('soleProprietorship',    'businessInterest', 'Sole proprietorship',         1),
  ('partnershipInterest',   'businessInterest', 'Partnership interest',        2),
  ('privateCompanyShares',  'businessInterest', 'Private company shares',      3),

  ('exchangeAccount',       'digitalAsset',     'Exchange account',            1),
  ('selfCustodyWallet',     'digitalAsset',     'Self-custody wallet',         2),
  ('digitalCollectible',    'digitalAsset',     'Digital collectible',         3),
  ('domainOrIntellectual',  'digitalAsset',     'Domain or intellectual property', 4),

  -- Section C of the product definition: the structured physical inventory.
  ('jewellery',             'physicalValuable', 'Jewellery',                   1),
  ('artwork',               'physicalValuable', 'Artwork',                     2),
  ('collectible',           'physicalValuable', 'Collectible',                 3),
  ('vehicle',               'physicalValuable', 'Vehicle',                     4),
  ('safeDepositBox',        'physicalValuable', 'Safe deposit box',            5),
  ('preciousMetal',         'physicalValuable', 'Precious metal',              6),

  ('customAsset',           'otherAsset',       'Other',                       1)
on conflict (subtype) do update set
  parent_category = excluded.parent_category,
  display_name    = excluded.display_name,
  sort_order      = excluded.sort_order;

-- =============================================================================================
-- 5 · estate_assets — the inventory itself
-- =============================================================================================
create table if not exists public.estate_assets (
  id                      uuid        primary key default gen_random_uuid(),
  estate_id               uuid        not null references public.estates(id) on delete cascade,
  created_by              uuid        not null references auth.users(id),

  -- Persist-both taxonomy, same discipline as documents: the fine subtype AND its coarse parent, so
  -- a client that has never heard of a new subtype can still group the row.
  category                text        not null references public.estate_asset_category(value),
  subtype                 text        not null references public.estate_asset_subtype(subtype),

  label                   text        not null,
  -- ★ THE SAME LADDER AS DOCUMENTS, ON PURPOSE. `document_grantable` is defined over exactly these
  -- five values, so an asset carrying a value from a DIFFERENT ladder could not be reasoned about by
  -- the ceiling the estate already has. One sensitivity vocabulary per estate, not two.
  -- (The catalog's NAME is document-flavoured; renaming it is a wider migration than this slice, and
  -- is ledgered rather than done here under cover of an inventory change.)
  sensitivity             text        not null default 'sealed' references public.document_sensitivity(value),

  owner_label             text,                     -- "Jointly held", "Held in trust" — free text
  country_code            text        check (country_code is null or country_code ~ '^[A-Z]{2}$'),
  jurisdiction            text,                     -- state / province / canton
  institution_name        text,
  -- ★ A HINT, AND THE SCHEMA ENFORCES THAT IT CANNOT BE MORE. Capped at 12 characters so a full
  -- account number, IBAN or wallet address is UNSTORABLE rather than merely discouraged. A field
  -- that can hold a secret eventually holds one.
  reference_hint          text        check (reference_hint is null or length(reference_hint) <= 12),

  approximate_value_cents bigint      check (approximate_value_cents is null or approximate_value_cents >= 0),
  currency                text        not null default 'USD' check (currency ~ '^[A-Z]{3}$'),
  notes                   text,
  -- Who is named AT THE INSTITUTION (an IRA beneficiary, a policy nominee). INFORMATIONAL RECORD
  -- KEEPING — it confers no access in this product and grants nothing.
  beneficiary_note        text,

  verification_status     text        not null default 'unverified'
                            check (verification_status in ('unverified','ownerAsserted','documented','verified')),

  -- Soft deletion. NULL = live. The pair is set and cleared together by the archive/restore RPCs.
  archived_at             timestamptz,
  archived_by             uuid        references auth.users(id),

  created_at              timestamptz not null default now(),
  updated_at              timestamptz not null default now(),

  constraint estate_assets_label_not_blank check (length(btrim(label)) > 0),
  constraint estate_assets_label_len       check (length(label) <= 200),
  constraint estate_assets_archived_pair   check ((archived_at is null) = (archived_by is null))
);
create index if not exists estate_assets_estate_idx on public.estate_assets (estate_id);
-- Partial index: the common read is "the live inventory", and archived rows drop out of it.
create index if not exists estate_assets_live_idx on public.estate_assets (estate_id, created_at desc)
  where archived_at is null;

alter table public.estate_assets enable row level security;

-- READ: estate OWNER ONLY, through the is_estate_owner DEFINER helper. An inline estate_memberships
-- subquery would FAIL here (authenticated holds no SELECT grant on it — the policy subquery runs as
-- the invoker), which is the same reason connections/normalized_assets use the helper.
--
-- ★ NO aal2 CLAUSE, PER THE RULING. This policy is the ONLY read path, and it admits the owner only.
drop policy if exists estate_assets_read_owner on public.estate_assets;
create policy estate_assets_read_owner on public.estate_assets
  for select to authenticated using (public.is_estate_owner(estate_id));

-- WRITES ARE DEFINER-RPC-ONLY — the documents posture (0030). No INSERT/UPDATE/DELETE grant exists,
-- so validation, the audit trail and the archive semantics cannot be bypassed by a direct PostgREST
-- write. The table keeps exactly ONE client grant: authenticated SELECT.
grant select on table public.estate_assets to authenticated;

-- =============================================================================================
-- 6 · estate_asset_documents — evidence attached to an asset
-- =============================================================================================
-- ★ THE JOIN CARRIES NO AUTHORITY OF ITS OWN. Linking a document to an asset does not widen who may
-- read either one: the document keeps `documents_read` (owner, or a covering grant) and the asset
-- keeps owner-only. A join row is a statement about organisation, never about access.
create table if not exists public.estate_asset_documents (
  asset_id  uuid        not null references public.estate_assets(id) on delete cascade,
  doc_id    uuid        not null references public.documents(id) on delete cascade,
  linked_by uuid        not null references auth.users(id),
  linked_at timestamptz not null default now(),
  primary key (asset_id, doc_id)
);
create index if not exists estate_asset_documents_doc_idx on public.estate_asset_documents (doc_id);

alter table public.estate_asset_documents enable row level security;

-- Readable exactly when the asset is readable. `estate_assets` is owner-only, so this resolves to the
-- owner — expressed as a dependency on the asset rather than a second copy of the ownership rule, so
-- the two cannot drift apart.
drop policy if exists estate_asset_documents_read on public.estate_asset_documents;
create policy estate_asset_documents_read on public.estate_asset_documents
  for select to authenticated using (
    exists (select 1 from public.estate_assets a where a.id = asset_id and public.is_estate_owner(a.estate_id))
  );
grant select on table public.estate_asset_documents to authenticated;
-- No write grant: link/unlink are DEFINER RPCs.

-- ★ ON DELETE CASCADE from `documents` is what keeps this table honest. A vault document is HARD
-- deleted (0039), so its join rows must go with it; leaving a dangling asset↔doc row would render an
-- attachment for a document that no longer exists.

-- =============================================================================================
-- 7 · vocabulary versioning — the new catalogs share the existing taxonomy_version counter
-- =============================================================================================
-- ★ ONE COUNTER, ONE CLIENT CACHE INVALIDATION. The client caches the asset vocabulary by
-- `vocabulary_version` exactly as it caches the document vocabulary. Giving the asset catalogs their
-- own counter would mean a client had to track two, and the one it forgot would serve a stale
-- vocabulary indefinitely. `bump_taxonomy_vocabulary_version` (0036) is reused verbatim.
drop trigger if exists estate_asset_category_taxonomy_bump on public.estate_asset_category;
create trigger estate_asset_category_taxonomy_bump
  after insert or update or delete on public.estate_asset_category
  for each statement execute function public.bump_taxonomy_vocabulary_version();

drop trigger if exists estate_asset_subtype_taxonomy_bump on public.estate_asset_subtype;
create trigger estate_asset_subtype_taxonomy_bump
  after insert or update or delete on public.estate_asset_subtype
  for each statement execute function public.bump_taxonomy_vocabulary_version();

-- ★ THE TRIGGERS ARE CREATED AFTER THE SEED, deliberately, matching 0036: attaching them first would
-- bump the version once per seed statement and hand every client a version number that describes
-- nothing. One bump on the next real change is the useful signal.

commit;

-- =============================================================================================
-- 8 · RPCs — APPLY db/functions/estate_asset_rpcs.sql IMMEDIATELY AFTER THIS FILE
-- =============================================================================================
-- The function bodies live in ONE place (db/functions/estate_asset_rpcs.sql) rather than being
-- duplicated here. Two copies of a SECURITY DEFINER body is a drift hazard with an authorization
-- gate inside it: the copy that gets patched is not necessarily the copy that is deployed.
--
-- `scripts/buildEstateAssetBundle.mjs` concatenates this file and that one into a single paste-ready
-- artifact, so the SQL editor still gets one paste.


-- ==== db/functions/estate_asset_rpcs.sql ==========================================================
-- Estate-asset RPCs — migration 0048 (Phase 9). Source of truth; re-apply on reset.
--
-- Owner-gated DEFINER doors for the MANUAL estate inventory. Every one of them:
--   * resolves the row FIRST and gates on the ROW's estate_id, never on a caller-supplied estate;
--   * raises machine-readable sentinels as the exception MESSAGE (errcode P0001/P0002/42501), the
--     same message-as-code convention as `unknown_subtype`;
--   * writes an audit entry naming the CHANGED FIELDS, never their values — an asset's value, notes
--     and reference hint must not be reconstructable from the audit log.
--
-- ★ THE CATEGORY IS DERIVED FROM THE SUBTYPE, NEVER ACCEPTED FROM THE CALLER. Taking both would let a
-- client persist a (category, subtype) pair the catalog contradicts — a persist-both taxonomy is only
-- trustworthy if exactly one of the pair is authoritative and the other is looked up.

-- ---------------------------------------------------------------------------------------------
-- get_estate_asset_taxonomy() -> jsonb  — the client read path for the asset vocabulary
-- ---------------------------------------------------------------------------------------------
-- ACTIVE values only, so presence in the payload IS the active-validation fact (no client is_active
-- check to forget). Shares `taxonomy_version` with the document catalogs so one version bump
-- invalidates one client cache.
create or replace function public.get_estate_asset_taxonomy()
 returns jsonb
 language sql
 security definer
 stable
 set search_path to 'public'
as $function$
  select jsonb_build_object(
    'schema_version',     (select schema_version     from public.taxonomy_version where id = 1),
    'vocabulary_version', (select vocabulary_version from public.taxonomy_version where id = 1),
    'categories', coalesce((
      select jsonb_agg(jsonb_build_object(
        'value', value, 'display_name', display_name, 'description', description,
        'sort_order', sort_order, 'icon_key', icon_key, 'is_physical', is_physical)
        order by sort_order, value)
      from public.estate_asset_category where is_active), '[]'::jsonb),
    'subtypes', coalesce((
      select jsonb_agg(jsonb_build_object(
        'value', subtype, 'display_name', display_name, 'description', description,
        'parent_category', parent_category, 'sort_order', sort_order, 'icon_key', icon_key)
        order by sort_order, subtype)
      from public.estate_asset_subtype where is_active), '[]'::jsonb)
  );
$function$;
revoke execute on function public.get_estate_asset_taxonomy() from public, anon;
grant  execute on function public.get_estate_asset_taxonomy() to authenticated;

-- ---------------------------------------------------------------------------------------------
-- create_estate_asset(...) -> uuid
-- ---------------------------------------------------------------------------------------------
create or replace function public.create_estate_asset(
  p_estate                  uuid,
  p_subtype                 text,
  p_label                   text,
  p_sensitivity             text    default null,
  p_owner_label             text    default null,
  p_country_code            text    default null,
  p_jurisdiction            text    default null,
  p_institution_name        text    default null,
  p_reference_hint          text    default null,
  p_approximate_value_cents bigint  default null,
  p_currency                text    default null,
  p_notes                   text    default null,
  p_beneficiary_note        text    default null
)
 returns uuid
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  v_uid      uuid := auth.uid();
  v_category text;
  v_sens     text;
  v_cur      text;
  v_id       uuid;
begin
  if v_uid is null then raise exception 'auth_required' using errcode = '42501'; end if;
  if not public.is_estate_owner(p_estate) then raise exception 'not_estate_owner' using errcode = '42501'; end if;

  if p_label is null or length(btrim(p_label)) = 0 then
    raise exception 'label_required' using errcode = 'P0001';
  end if;
  if length(p_label) > 200 then
    raise exception 'label_too_long' using errcode = 'P0001';
  end if;

  -- Catalog interrogation. An unknown or retired subtype is refused BEFORE any row exists — the
  -- Vault lesson: a rejection that lands after the write leaves an orphan behind.
  select s.parent_category into v_category
    from public.estate_asset_subtype s
    where s.subtype = p_subtype and s.is_active;
  if not found then
    if exists (select 1 from public.estate_asset_subtype where subtype = p_subtype) then
      raise exception 'inactive_subtype' using errcode = 'P0001';
    else
      raise exception 'unknown_subtype' using errcode = 'P0001';
    end if;
  end if;

  -- Sensitivity defaults to the most protective level, and an explicit value is validated against the
  -- SAME catalog documents use. There is no fallback: an unknown value is refused, never coerced.
  v_sens := coalesce(p_sensitivity, 'sealed');
  if not exists (select 1 from public.document_sensitivity where value = v_sens and is_active) then
    raise exception 'invalid_sensitivity' using errcode = 'P0001';
  end if;

  v_cur := upper(coalesce(p_currency, 'USD'));
  if v_cur !~ '^[A-Z]{3}$' then raise exception 'invalid_currency' using errcode = 'P0001'; end if;

  if p_approximate_value_cents is not null and p_approximate_value_cents < 0 then
    raise exception 'invalid_value' using errcode = 'P0001';
  end if;
  if p_reference_hint is not null and length(p_reference_hint) > 12 then
    -- The column CHECK would refuse this too; raising here turns a constraint violation into a
    -- sentinel the client can explain.
    raise exception 'reference_hint_too_long' using errcode = 'P0001';
  end if;

  -- ★ THIS CHECK WAS MISSING, AND ITS ABSENCE LEAKED THE WHOLE ROW. `update_estate_asset` validated
  -- the country code and this function did not, so a bad code fell through to the column CHECK —
  -- and a Postgres constraint violation carries `DETAIL: Failing row contains (…)`, i.e. the
  -- approximate value, the notes, the beneficiary note and the reference hint, into the server log
  -- and into any error telemetry downstream. The client maps the unrecognized message to `unknown`
  -- and shows nothing, which is exactly why this would never have been noticed from the app.
  --
  -- Every user-supplied field on this path is now validated BEFORE the insert, so a constraint
  -- violation here means a genuine bug rather than ordinary bad input.
  if p_country_code is not null and btrim(p_country_code) <> ''
     and upper(btrim(p_country_code)) !~ '^[A-Z]{2}$' then
    raise exception 'invalid_country_code' using errcode = 'P0001';
  end if;

  insert into public.estate_assets (
    estate_id, created_by, category, subtype, label, sensitivity, owner_label, country_code,
    jurisdiction, institution_name, reference_hint, approximate_value_cents, currency, notes,
    beneficiary_note
  ) values (
    p_estate, v_uid, v_category, p_subtype, btrim(p_label), v_sens, p_owner_label,
    nullif(upper(btrim(coalesce(p_country_code, ''))), ''), p_jurisdiction, p_institution_name,
    p_reference_hint, p_approximate_value_cents, v_cur, p_notes, p_beneficiary_note
  ) returning id into v_id;

  -- FIELD NAMES ONLY. An estate's asset values must not be reconstructable from audit_logs.
  perform public.write_audit('estate_asset.created', 'estate_assets', v_id, p_estate,
    jsonb_build_object('category', v_category, 'subtype', p_subtype, 'sensitivity', v_sens,
                       'via', 'create_estate_asset'));
  return v_id;
end;
$function$;
revoke execute on function public.create_estate_asset(uuid, text, text, text, text, text, text, text, text, bigint, text, text, text) from public, anon;
grant  execute on function public.create_estate_asset(uuid, text, text, text, text, text, text, text, text, bigint, text, text, text) to authenticated;

-- ---------------------------------------------------------------------------------------------
-- update_estate_asset(...) -> void  — METADATA ONLY
-- ---------------------------------------------------------------------------------------------
-- ★ THE IMMUTABLE FIELDS ARE UNREPRESENTABLE. `estate_id`, `created_by` and `created_at` are not
-- parameters, so a caller cannot move an asset to another estate or rewrite its provenance — the
-- strongest form of "rejected", exactly as `update_vault_document` treats storage_path.
--
-- ★ NULL MEANS "LEAVE ALONE", so a client may send only what changed. The consequence is that a
-- nullable field cannot be CLEARED through this door; `p_clear` names the fields to blank, which
-- keeps "unset it" explicit instead of overloading NULL with two meanings.
create or replace function public.update_estate_asset(
  p_asset_id                uuid,
  p_subtype                 text    default null,
  p_label                   text    default null,
  p_sensitivity             text    default null,
  p_owner_label             text    default null,
  p_country_code            text    default null,
  p_jurisdiction            text    default null,
  p_institution_name        text    default null,
  p_reference_hint          text    default null,
  p_approximate_value_cents bigint  default null,
  p_currency                text    default null,
  p_notes                   text    default null,
  p_beneficiary_note        text    default null,
  p_verification_status     text    default null,
  p_clear                   text[]  default null
)
 returns void
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  v_uid      uuid := auth.uid();
  v_estate   uuid;
  v_arch     timestamptz;
  v_category text;
  v_changed  text[] := '{}';
  v_field    text;
begin
  if v_uid is null then raise exception 'auth_required' using errcode = '42501'; end if;

  select estate_id, archived_at into v_estate, v_arch from public.estate_assets where id = p_asset_id;
  if not found then raise exception 'asset_not_found' using errcode = 'P0002'; end if;
  if not public.is_estate_owner(v_estate) then raise exception 'not_estate_owner' using errcode = '42501'; end if;
  -- An archived asset is restored before it is edited. Editing something the owner has removed from
  -- the inventory would silently resurrect it in every list that filters on archived_at.
  if v_arch is not null then raise exception 'asset_archived' using errcode = 'P0001'; end if;

  if p_subtype is null and p_label is null and p_sensitivity is null and p_owner_label is null
     and p_country_code is null and p_jurisdiction is null and p_institution_name is null
     and p_reference_hint is null and p_approximate_value_cents is null and p_currency is null
     and p_notes is null and p_beneficiary_note is null and p_verification_status is null
     and (p_clear is null or array_length(p_clear, 1) is null) then
    raise exception 'no_fields_to_update' using errcode = 'P0001';
  end if;

  if p_label is not null then
    if length(btrim(p_label)) = 0 then raise exception 'label_required' using errcode = 'P0001'; end if;
    if length(p_label) > 200 then raise exception 'label_too_long' using errcode = 'P0001'; end if;
    update public.estate_assets set label = btrim(p_label) where id = p_asset_id;
    v_changed := array_append(v_changed, 'label');
  end if;

  if p_subtype is not null then
    select s.parent_category into v_category
      from public.estate_asset_subtype s where s.subtype = p_subtype and s.is_active;
    if not found then
      if exists (select 1 from public.estate_asset_subtype where subtype = p_subtype) then
        raise exception 'inactive_subtype' using errcode = 'P0001';
      else
        raise exception 'unknown_subtype' using errcode = 'P0001';
      end if;
    end if;
    -- The category is RE-DERIVED, never taken from the caller — the pair cannot be made inconsistent.
    update public.estate_assets set subtype = p_subtype, category = v_category where id = p_asset_id;
    v_changed := array_append(v_changed, 'subtype');
    v_changed := array_append(v_changed, 'category');
  end if;

  if p_sensitivity is not null then
    if not exists (select 1 from public.document_sensitivity where value = p_sensitivity and is_active) then
      raise exception 'invalid_sensitivity' using errcode = 'P0001';
    end if;
    update public.estate_assets set sensitivity = p_sensitivity where id = p_asset_id;
    v_changed := array_append(v_changed, 'sensitivity');
  end if;

  if p_verification_status is not null then
    if p_verification_status not in ('unverified','ownerAsserted','documented','verified') then
      raise exception 'invalid_verification_status' using errcode = 'P0001';
    end if;
    update public.estate_assets set verification_status = p_verification_status where id = p_asset_id;
    v_changed := array_append(v_changed, 'verification_status');
  end if;

  if p_currency is not null then
    if upper(p_currency) !~ '^[A-Z]{3}$' then raise exception 'invalid_currency' using errcode = 'P0001'; end if;
    update public.estate_assets set currency = upper(p_currency) where id = p_asset_id;
    v_changed := array_append(v_changed, 'currency');
  end if;

  if p_approximate_value_cents is not null then
    if p_approximate_value_cents < 0 then raise exception 'invalid_value' using errcode = 'P0001'; end if;
    update public.estate_assets set approximate_value_cents = p_approximate_value_cents where id = p_asset_id;
    v_changed := array_append(v_changed, 'approximate_value_cents');
  end if;

  if p_reference_hint is not null then
    if length(p_reference_hint) > 12 then raise exception 'reference_hint_too_long' using errcode = 'P0001'; end if;
    update public.estate_assets set reference_hint = p_reference_hint where id = p_asset_id;
    v_changed := array_append(v_changed, 'reference_hint');
  end if;

  if p_country_code is not null then
    if upper(btrim(p_country_code)) !~ '^[A-Z]{2}$' then
      raise exception 'invalid_country_code' using errcode = 'P0001';
    end if;
    update public.estate_assets set country_code = upper(btrim(p_country_code)) where id = p_asset_id;
    v_changed := array_append(v_changed, 'country_code');
  end if;

  if p_owner_label is not null then
    update public.estate_assets set owner_label = p_owner_label where id = p_asset_id;
    v_changed := array_append(v_changed, 'owner_label');
  end if;
  if p_jurisdiction is not null then
    update public.estate_assets set jurisdiction = p_jurisdiction where id = p_asset_id;
    v_changed := array_append(v_changed, 'jurisdiction');
  end if;
  if p_institution_name is not null then
    update public.estate_assets set institution_name = p_institution_name where id = p_asset_id;
    v_changed := array_append(v_changed, 'institution_name');
  end if;
  if p_notes is not null then
    update public.estate_assets set notes = p_notes where id = p_asset_id;
    v_changed := array_append(v_changed, 'notes');
  end if;
  if p_beneficiary_note is not null then
    update public.estate_assets set beneficiary_note = p_beneficiary_note where id = p_asset_id;
    v_changed := array_append(v_changed, 'beneficiary_note');
  end if;

  -- Explicit clearing. Only genuinely optional columns are clearable — `label`, `subtype`,
  -- `category`, `sensitivity` and `currency` are NOT NULL and are absent from this list by design.
  if p_clear is not null then
    foreach v_field in array p_clear loop
      case v_field
        when 'owner_label'             then update public.estate_assets set owner_label = null where id = p_asset_id;
        when 'country_code'            then update public.estate_assets set country_code = null where id = p_asset_id;
        when 'jurisdiction'            then update public.estate_assets set jurisdiction = null where id = p_asset_id;
        when 'institution_name'        then update public.estate_assets set institution_name = null where id = p_asset_id;
        when 'reference_hint'          then update public.estate_assets set reference_hint = null where id = p_asset_id;
        when 'approximate_value_cents' then update public.estate_assets set approximate_value_cents = null where id = p_asset_id;
        when 'notes'                   then update public.estate_assets set notes = null where id = p_asset_id;
        when 'beneficiary_note'        then update public.estate_assets set beneficiary_note = null where id = p_asset_id;
        else raise exception 'unclearable_field' using errcode = 'P0001';
      end case;
      v_changed := array_append(v_changed, 'cleared:' || v_field);
    end loop;
  end if;

  update public.estate_assets set updated_at = now() where id = p_asset_id;

  perform public.write_audit('estate_asset.updated', 'estate_assets', p_asset_id, v_estate,
    jsonb_build_object('changed', to_jsonb(v_changed), 'via', 'update_estate_asset'));
end;
$function$;
revoke execute on function public.update_estate_asset(uuid, text, text, text, text, text, text, text, text, bigint, text, text, text, text, text[]) from public, anon;
grant  execute on function public.update_estate_asset(uuid, text, text, text, text, text, text, text, text, bigint, text, text, text, text, text[]) to authenticated;

-- ---------------------------------------------------------------------------------------------
-- archive_estate_asset / restore_estate_asset -> void  — the SOFT delete pair
-- ---------------------------------------------------------------------------------------------
-- ★ NOTHING IS DESTROYED AND NOTHING IS DETACHED. Archiving sets a timestamp; attached documents keep
-- their own hard-delete lifecycle untouched. This is the owner-approved asymmetry with documents: a
-- document's irreversibility is justified by a storage-byte purge, and an asset has no bytes.
create or replace function public.archive_estate_asset(p_asset_id uuid)
 returns void
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  v_uid    uuid := auth.uid();
  v_estate uuid;
  v_arch   timestamptz;
begin
  if v_uid is null then raise exception 'auth_required' using errcode = '42501'; end if;
  select estate_id, archived_at into v_estate, v_arch from public.estate_assets where id = p_asset_id;
  if not found then raise exception 'asset_not_found' using errcode = 'P0002'; end if;
  if not public.is_estate_owner(v_estate) then raise exception 'not_estate_owner' using errcode = '42501'; end if;
  -- Idempotent by refusal rather than by silence: a no-op success would tell the client the state
  -- changed when it did not.
  if v_arch is not null then raise exception 'already_archived' using errcode = 'P0001'; end if;

  update public.estate_assets
     set archived_at = now(), archived_by = v_uid, updated_at = now()
   where id = p_asset_id;

  perform public.write_audit('estate_asset.archived', 'estate_assets', p_asset_id, v_estate,
    jsonb_build_object('via', 'archive_estate_asset'));
end;
$function$;
revoke execute on function public.archive_estate_asset(uuid) from public, anon;
grant  execute on function public.archive_estate_asset(uuid) to authenticated;

create or replace function public.restore_estate_asset(p_asset_id uuid)
 returns void
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  v_uid    uuid := auth.uid();
  v_estate uuid;
  v_arch   timestamptz;
begin
  if v_uid is null then raise exception 'auth_required' using errcode = '42501'; end if;
  select estate_id, archived_at into v_estate, v_arch from public.estate_assets where id = p_asset_id;
  if not found then raise exception 'asset_not_found' using errcode = 'P0002'; end if;
  if not public.is_estate_owner(v_estate) then raise exception 'not_estate_owner' using errcode = '42501'; end if;
  if v_arch is null then raise exception 'not_archived' using errcode = 'P0001'; end if;

  update public.estate_assets
     set archived_at = null, archived_by = null, updated_at = now()
   where id = p_asset_id;

  perform public.write_audit('estate_asset.restored', 'estate_assets', p_asset_id, v_estate,
    jsonb_build_object('via', 'restore_estate_asset'));
end;
$function$;
revoke execute on function public.restore_estate_asset(uuid) from public, anon;
grant  execute on function public.restore_estate_asset(uuid) to authenticated;

-- ---------------------------------------------------------------------------------------------
-- link_asset_document / unlink_asset_document -> void
-- ---------------------------------------------------------------------------------------------
-- ★ BOTH SIDES ARE OWNERSHIP-CHECKED, AND BOTH MUST BE THE SAME ESTATE. Checking only the asset would
-- let an owner attach a document from an estate they do not own — the join row itself grants nothing,
-- but it would leak the document's EXISTENCE into a surface they control.
create or replace function public.link_asset_document(p_asset_id uuid, p_doc_id uuid)
 returns void
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  v_uid        uuid := auth.uid();
  v_asset_est  uuid;
  v_doc_est    uuid;
begin
  if v_uid is null then raise exception 'auth_required' using errcode = '42501'; end if;

  select estate_id into v_asset_est from public.estate_assets where id = p_asset_id;
  if not found then raise exception 'asset_not_found' using errcode = 'P0002'; end if;
  select estate_id into v_doc_est from public.documents where id = p_doc_id;
  if not found then raise exception 'document_not_found' using errcode = 'P0002'; end if;

  if not public.is_estate_owner(v_asset_est) then raise exception 'not_estate_owner' using errcode = '42501'; end if;
  if v_asset_est <> v_doc_est then raise exception 'cross_estate_link' using errcode = '42501'; end if;

  insert into public.estate_asset_documents (asset_id, doc_id, linked_by)
  values (p_asset_id, p_doc_id, v_uid)
  on conflict (asset_id, doc_id) do nothing;

  perform public.write_audit('estate_asset.document_linked', 'estate_assets', p_asset_id, v_asset_est,
    jsonb_build_object('doc_id', p_doc_id, 'via', 'link_asset_document'));
end;
$function$;
revoke execute on function public.link_asset_document(uuid, uuid) from public, anon;
grant  execute on function public.link_asset_document(uuid, uuid) to authenticated;

create or replace function public.unlink_asset_document(p_asset_id uuid, p_doc_id uuid)
 returns void
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  v_uid       uuid := auth.uid();
  v_asset_est uuid;
begin
  if v_uid is null then raise exception 'auth_required' using errcode = '42501'; end if;
  select estate_id into v_asset_est from public.estate_assets where id = p_asset_id;
  if not found then raise exception 'asset_not_found' using errcode = 'P0002'; end if;
  if not public.is_estate_owner(v_asset_est) then raise exception 'not_estate_owner' using errcode = '42501'; end if;

  delete from public.estate_asset_documents where asset_id = p_asset_id and doc_id = p_doc_id;

  -- ★ UNLINKING DELETES NO BYTES AND NO DOCUMENT ROW. Detaching evidence from an asset is an
  -- organisational act; removing the document itself remains `delete_vault_document`, with its own
  -- blocking gauntlet and purge outbox.
  perform public.write_audit('estate_asset.document_unlinked', 'estate_assets', p_asset_id, v_asset_est,
    jsonb_build_object('doc_id', p_doc_id, 'via', 'unlink_asset_document'));
end;
$function$;
revoke execute on function public.unlink_asset_document(uuid, uuid) from public, anon;
grant  execute on function public.unlink_asset_document(uuid, uuid) to authenticated;


-- ==== db/functions/create_asset_grant.sql =========================================================
-- public.create_asset_grant(
--   p_estate_id uuid, p_grantee_user_id uuid, p_grantee_role text,
--   p_category text, p_visibility_tier text, p_release_condition text,
--   p_professional_type text default null, p_requires_step_up boolean default false)
--   -> SETOF public.access_grants   (the created grant row)
--
-- B2b — the audited, single-entry interface for creating a CATEGORY-scoped ASSET disclosure grant
-- (the connected-financial-data counterpart of create_document_grant, which is document-only by
-- design). Category-scoped: takes p_category (one of the asset categories), never a document_id —
-- the document_id XOR category table invariant is satisfied structurally (document_id stays NULL).
--
-- WRITE-TIME CEILING (the load-bearing addition): the enforce_grant_ceiling TRIGGER only fires for
-- per-document grants (new.document_id is not null), so category grants bypass it. This RPC enforces
-- the asset ceiling explicitly via asset_category_grantable(role, category, tier) BEFORE the insert —
-- an over-ceiling grant (e.g. beneficiary + account_balances + full_detail) is REJECTED at write, not
-- merely clamped at read. B2a's read-time clamp in list_estate_assets remains the backstop, so a bad
-- grant can neither be stored (this) nor leak (that). Defense-in-depth on a financial-disclosure grant.
--
-- SECURITY (load-bearing): SECURITY DEFINER runs as the table owner and BYPASSES RLS, so the
-- access_grants_insert WITH CHECK (is_estate_owner) does NOT auto-apply. The explicit
-- is_estate_owner(p_estate_id) check below IS the access boundary — FIRST check after the auth.uid()
-- null-guard, BEFORE any insert. Without it any authenticated user could grant themselves access.
--
-- Pre-granting is allowed (matches create_document_grant + the B2a grant-based read): the RPC does
-- NOT require the grantee to be a member. A grant to a uid that hasn't joined is inert until that uid
-- authenticates (access re-evaluated at read against auth.uid()) — no hole, an unmatched grant never
-- activates.
--
-- UUID-case: p_grantee_user_id is uuid-typed -> Postgres canonicalizes to lowercase automatically.
--
-- Error codes (SQLSTATE -> PostgREST HTTP; only mapped SQLSTATEs avoid 500):
--   42501 -> 403  unauthenticated / not_estate_owner (privilege gate) / ceiling violation
--   23505 -> 409  duplicate: an active grant already exists for this category + grantee
--   P0001 -> 400  validation: owner_grant (self/owner) OR invalid asset category
--
-- SECURITY DEFINER; relies on auth.uid(). Source of truth — re-apply on DB reset.

create or replace function public.create_asset_grant(
  p_estate_id uuid,
  p_grantee_user_id uuid,
  p_grantee_role text,
  p_category text,
  p_visibility_tier text,
  p_release_condition text,
  p_professional_type text default null,
  p_requires_step_up boolean default false
)
 returns setof public.access_grants
 language plpgsql
 security definer
 set search_path to 'public', 'extensions'
as $function$
declare
  v_user uuid := auth.uid();
  v_id uuid;
begin
  -- Auth null-guard.
  if v_user is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  -- SECURITY SPINE (privilege-escalation gate). DEFINER bypasses RLS, so this explicit owner-check
  -- IS the access boundary and MUST precede any insert.
  if not public.is_estate_owner(p_estate_id) then
    raise exception 'not estate owner' using errcode = '42501';
  end if;

  -- No grants to owners (self, or any ownership-role member) — inherent access.
  if p_grantee_user_id = v_user
     or exists (
       select 1 from public.estate_memberships m
       where m.estate_id = p_estate_id
         and m.user_id = p_grantee_user_id
         and public.is_ownership_role(m.role)
     ) then
    raise exception 'cannot grant access to an owner; owners have inherent access';  -- P0001 -> 400
  end if;

  -- Category must be a real ASSET category (defense-in-depth beyond the access_grants.category CHECK;
  -- the RPC is the security boundary and may be called directly).
  --
  -- ★ `estate_inventory` IS IN THIS LIST IN VERSION CONTROL — AND UNTIL PHASE 10-E IT WAS NOT.
  --
  -- Migration 0049 adds it to the DEPLOYED body by string surgery: it reads `pg_get_functiondef`,
  -- replaces this exact literal, and re-executes. So production has had the widened list for weeks
  -- while this file — the supposed source of truth — still refused the category.
  --
  -- That is the live-only-object trap this repository has been bitten by repeatedly (handle_new_user,
  -- is_estate_owner, the whole 0009 notifications table), except inverted and more dangerous: the
  -- object WAS in version control, and the version-controlled copy was WRONG. Re-applying this file
  -- would have silently reverted Phase 9/10-A grantability, and nothing would have caught it — the
  -- deployed-contract verifier checks `asset_category_grantable`, which is a DIFFERENT function and
  -- would have stayed green.
  --
  -- It became reachable in Phase 10-E because this file now ships in a bundle. Fixed at the source
  -- rather than by ordering the bundles carefully, because an ordering rule is a thing to remember
  -- and a correct source file is not. 0049's patch is guarded by `if position('estate_inventory' in
  -- v_src) = 0`, so it now finds the category already present and does nothing — still correct for a
  -- database that predates this fix, a no-op for one that does not.
  if p_category not in
     ('account_balances', 'institution_names', 'total_asset_value', 'linked_account_details', 'estate_inventory') then
    raise exception 'invalid asset category: %', p_category;  -- P0001 -> 400
  end if;

  -- ★ WRITE-TIME RELEASE VOCABULARY (Phase 11-B). The table CHECK still accepts the deprecated
  --   `after_verified_death_or_incapacity` so stored rows stay readable and unreinterpreted; this
  --   gate is what stops a NEW row from carrying the fused ambiguity. Death and incapacity are now
  --   expressible separately — and neither is satisfied by anything, so this widens what an owner
  --   may EXPRESS, never what a grantee may SEE.
  if not public.release_condition_writable(p_release_condition) then
    raise exception 'unsupported release condition: %', p_release_condition;  -- P0001 -> 400
  end if;

  -- ★ WRITE-TIME CEILING — reject an over-ceiling grant before storing it (the trigger skips category
  --   grants). Mirrors the read-time clamp in list_estate_assets: e.g. beneficiary + account_balances
  --   + full_detail -> asset_category_grantable = false -> rejected here.
  if not public.asset_category_grantable(p_grantee_role, p_category, p_visibility_tier) then
    raise exception 'asset grant ceiling: role % cannot be granted tier % for category %',
      p_grantee_role, p_visibility_tier, p_category
      using errcode = '42501';   -- ceiling violation -> 403 (mirrors document_grantable)
  end if;

  -- Insert (category-scoped: document_id NULL). Table CHECKs + the one-active-grant-per-(estate,
  -- grantee,category) unique index fire regardless of the DEFINER context. Catch the unique
  -- violation and surface a readable 409 (fail, never silent upsert — a silent tier change on a
  -- disclosure grant is dangerous; a tier change is revoke + re-create).
  begin
    insert into public.access_grants
      (estate_id, grantee_user_id, grantee_role, professional_type,
       document_id, category, visibility_tier, release_condition,
       requires_step_up, granted_by_user_id)
    values
      (p_estate_id, p_grantee_user_id, p_grantee_role, p_professional_type,
       null, p_category, p_visibility_tier, p_release_condition,
       p_requires_step_up, v_user)
    returning id into v_id;
  exception
    when unique_violation then
      raise exception
        'an active grant already exists for this category and grantee; revoke it first'
        using errcode = '23505';   -- unique_violation -> 409 Conflict
  end;

  perform public.write_audit(
    'access_grant.created',
    'access_grants',
    v_id,
    p_estate_id,
    jsonb_build_object(
      'grantee_user_id', p_grantee_user_id,
      'grantee_role', p_grantee_role,
      'category', p_category,
      'visibility_tier', p_visibility_tier,
      'release_condition', p_release_condition
    )
  );

  -- ★ PHASE 10-E — REWRITTEN, AND THE PREVIOUS VERSION WAS A LIVE DEFECT ON TWO COUNTS.
  --
  -- It read:
  --     'You''ve been granted access to estate assets (' || p_category || ').'
  --     'afterworth://accounts'
  --     jsonb_build_object('kind','grant_created','grant_id', v_id, 'category', p_category)
  --
  -- 1. It concatenated `p_category` — a backend enum — into user-facing prose. The one lifecycle
  --    notification in production reads "...to estate assets (estate_inventory)." on a real device.
  --    The mobile client HAS an audit forbidding backend vocabulary on screen; it never fired,
  --    because the enum arrived as server-authored copy rather than as a client-rendered value.
  --    This is exactly why copy is now a constant looked up by event name.
  -- 2. `afterworth://accounts` is not a route this app has (the route is `/assets`), so the link was
  --    inert — fail-closed by the client allowlist, but a promise the product could not keep.
  --    The payload additionally carried a raw grant id and category, which nothing needs.
  --
  -- ★ AND IT EMITTED UNCONDITIONALLY, WHICH IS THE MORE SERIOUS HALF. "You have access" was sent for
  -- ANY grant this function created, including a `after_verified_death_or_incapacity` one that
  -- releases nothing and must stay dormant until Phase 11 connects activation to release. The gate
  -- below is the death/claim firewall: a grant that is not live RIGHT NOW produces silence.
  --
  -- ★ THE GATE READS THE STORED ROW, NOT THE PARAMETERS. `status` and `approved_at` are column
  -- DEFAULTS here — the insert names neither — so deciding from `p_release_condition` alone would be
  -- reasoning about the arguments rather than about what was actually written. A future default
  -- change, or a trigger, would silently make the parameter-based answer wrong while looking right.
  if exists (
    select 1 from public.access_grants g
    where g.id = v_id
      and public.notification_grant_is_live(g.status, g.release_condition, g.approved_at)
  ) then
    perform public.emit_lifecycle_notification(
      p_grantee_user_id,
      p_estate_id,
      'access_grant.created',
      public.notification_estate_home(p_estate_id, p_grantee_user_id)
    );
  end if;

  return query select g.* from public.access_grants g where g.id = v_id;
end;
$function$;


-- ==== db/functions/list_estate_assets.sql =========================================================
-- public.list_estate_assets(p_estate_id uuid) -> SETOF (redacted asset rows)
--
-- B2a — the SERVER-SIDE asset redaction (the security core). Owner -> full rows; non-owner ->
-- rows redacted to the caller's per-category grant tiers. SECURITY DEFINER so it reads
-- normalized_assets (which is OWNER-ONLY at the RLS layer — a beneficiary cannot SELECT it
-- directly, so the RAW balance is structurally unreachable outside this function). The RAW
-- balance_cents / holdings are NEVER returned for a non-owner below the disclosing tiers — they
-- are nulled/bucketed/summarized IN this function before any bytes leave the backend.
--
-- Tiers (per the account_balances grant, the primary value gate):
--   full_detail    -> exact balance + holdings (holdings also need linked_account_details=full_detail)
--   limited_detail -> exact balance, NO holdings
--   category_summary -> per-asset balance NULL; range_low/high_cents = BRACKETED group total
--                       (sum over asset_group, THEN bracketed — never an exact figure, so a
--                        single-asset group cannot leak its lone balance)
--   range_only     -> per-asset balance NULL; range_low/high_cents = per-asset coarse bracket
--   hidden         -> account row shows, NO value at all
--   (no grant)     -> the beneficiary sees NO asset rows (default-deny, safe)
-- INVARIANT: for a non-owner, NO returned field ever holds an exact value below limited_detail —
-- balance_cents is NULL, and the only value signal (range_low/high) is always a coarse bracket.
-- institution_names grant gates institution_name; linked_account_details gates masked_identifier +
-- holdings. Read-time ceiling re-check (asset_category_grantable) clamps an over-ceiling grant to
-- hidden (authoritative even if a grant predates a ceiling tightening).
--
-- Error model: unauthenticated / non-member -> empty set (never an error, never data).

-- --- helper: resolve a beneficiary's active tier for one asset category (SLICE 1: immediate only) ---
create or replace function public.asset_grant_tier(p_estate uuid, p_uid uuid, p_category text)
 returns text
 language sql
 stable
 security definer
 set search_path to 'public'
as $$
  select g.visibility_tier
  from public.access_grants g
  where g.estate_id = p_estate
    and g.grantee_user_id = p_uid
    and g.category = p_category
    and g.status = 'active'
    -- ★ PHASE 11-B — the canonical predicate. `legacy_immediate_only` is this surface's answer
    -- carried forward verbatim: the asset-value paths have never honoured an approval-conditioned
    -- grant, and 11-B centralizes the AUTHORITY without spending a product decision on the POLICY.
    -- 11-D wires the authoritative lifecycle through as an argument like every consumer — and under
    -- THIS policy it changes nothing: death-conditioned grants stay dormant on the asset surfaces
    -- even at death_verified (R12 keeps the policies distinct). Signal-based conditions and 'never'
    -- stay dormant-deny (A.4); an unknown condition or lifecycle refuses.
    and public.release_condition_satisfied(g.release_condition, g.approved_at, 'legacy_immediate_only',
                                           public.estate_lifecycle_state(p_estate))
  limit 1;
$$;

-- --- helper: coarse value brackets for range_only (THE POLICY KNOB — tune the brackets) ---
create or replace function public.asset_bracket_low(p bigint) returns bigint language sql immutable as $$
  select case
    when p < 1000000    then 0             when p < 5000000    then 1000000
    when p < 10000000   then 5000000       when p < 25000000   then 10000000
    when p < 50000000   then 25000000      when p < 100000000  then 50000000
    when p < 500000000  then 100000000     when p < 1000000000 then 500000000
    else 1000000000 end;
$$;
create or replace function public.asset_bracket_high(p bigint) returns bigint language sql immutable as $$
  select case
    when p < 1000000    then 1000000       when p < 5000000    then 5000000
    when p < 10000000   then 10000000      when p < 25000000   then 25000000
    when p < 50000000   then 50000000      when p < 100000000  then 100000000
    when p < 500000000  then 500000000     when p < 1000000000 then 1000000000
    else null end;   -- top bracket ($10M+): open-ended
$$;

-- --- the redaction RPC ---
create or replace function public.list_estate_assets(p_estate_id uuid)
 returns table (
   id uuid, estate_id uuid, connection_id uuid, institution_name text, provider_name text,
   asset_group text, asset_category text, asset_subtype text, source_type text,
   masked_identifier text, balance_cents bigint, currency text, holdings jsonb,
   refresh_timestamp timestamptz, last_sync_status text, confidence_level text,
   verification_status text, created_at timestamptz,
   resolved_tier text, range_low_cents bigint, range_high_cents bigint
 )
 language plpgsql
 stable
 security definer
 set search_path to 'public'
as $function$
declare
  v_uid   uuid := auth.uid();
  v_role  text;
  v_bal   text;   -- account_balances tier
  v_inst  text;   -- institution_names tier
  v_det   text;   -- linked_account_details tier
begin
  if v_uid is null then return; end if;

  -- OWNER: inherent full value, no redaction.
  if public.is_estate_owner(p_estate_id) then
    -- aal2 GATE (option b): the owner branch emits EXACT balance_cents + holdings -> require MFA,
    -- UNCONDITIONALLY. (DEFINER bypasses RLS; the gate must be inline.)
    perform public.require_aal2();
    return query
      select a.id, a.estate_id, a.connection_id, a.institution_name, a.provider_name,
             a.asset_group, a.asset_category, a.asset_subtype, a.source_type,
             a.masked_identifier, a.balance_cents, a.currency, a.holdings,
             a.refresh_timestamp, a.last_sync_status, a.confidence_level,
             a.verification_status, a.created_at,
             'full_detail'::text, null::bigint, null::bigint
      from public.normalized_assets a
      where a.estate_id = p_estate_id
      order by a.created_at desc;
    return;
  end if;

  -- NON-OWNER: GRANT-BASED, like can_access_document — NOT membership-gated. A grantee reads via
  -- their grant even without an estate_memberships row (the documents precedent; a beneficiary can
  -- hold grants before/without a membership). grantee_role comes from the GRANT (explicit, singular),
  -- not the membership — so no multi-membership role-derivation ambiguity. The account_balances
  -- grant is the primary gate + the role source.
  select g.visibility_tier, g.grantee_role into v_bal, v_role
  from public.access_grants g
  where g.estate_id = p_estate_id
    and g.grantee_user_id = v_uid
    and g.category = 'account_balances'
    and g.status = 'active'
    -- ★ PHASE 11-B — canonical predicate, `legacy_immediate_only` (see asset_grant_tier above).
    -- 11-D: lifecycle wired through; inert under this policy, by decision (R12).
    and public.release_condition_satisfied(g.release_condition, g.approved_at, 'legacy_immediate_only',
                                           public.estate_lifecycle_state(p_estate_id))
  limit 1;

  -- No account_balances grant -> the non-owner sees NO asset rows (default-deny, safe).
  if v_bal is null then return; end if;

  v_inst := public.asset_grant_tier(p_estate_id, v_uid, 'institution_names');
  v_det  := public.asset_grant_tier(p_estate_id, v_uid, 'linked_account_details');

  -- Read-time ceiling re-check (authoritative), applied to EVERY resolved tier uniformly: an
  -- over-ceiling grant collapses to hidden, even if the grant predates a ceiling tightening. This
  -- is what makes exact value UNREACHABLE for a beneficiary — asset_category_grantable caps
  -- 'account_balances' at category_summary for role 'beneficiary', so v_bal can never become
  -- limited_detail/full_detail for them (the balance_cents AND holdings gates both key off v_bal).
  if not public.asset_category_grantable(v_role, 'account_balances', v_bal) then
    v_bal := 'hidden';
  end if;
  if v_inst is not null and not public.asset_category_grantable(v_role, 'institution_names', v_inst) then
    v_inst := 'hidden';
  end if;
  if v_det is not null and not public.asset_category_grantable(v_role, 'linked_account_details', v_det) then
    v_det := 'hidden';
  end if;

  -- aal2 GATE (option b) — TIER-AWARE, THE CORRECTNESS-CRITICAL PLACEMENT. Placed AFTER the ceiling
  -- re-check so it keys off the FINAL resolved tier. A non-owner sees EXACT balance_cents only at
  -- limited_detail/full_detail (and holdings only at full_detail, which implies v_bal='full_detail'),
  -- so this single check covers every exact-value field. Beneficiary tiers (range_only/category_summary)
  -- and hidden emit brackets/NULL -> NO exact value -> stay aal1 (the payoff of option b). Because
  -- asset_category_grantable caps 'account_balances' at category_summary for role 'beneficiary',
  -- v_bal can never reach limited/full for them, so this can only fire for a professional.
  if v_bal in ('limited_detail', 'full_detail') then
    perform public.require_aal2();
  end if;

  return query
    select
      a.id, a.estate_id, a.connection_id,
      -- institution name gated by institution_names (hidden/none -> masked)
      case when coalesce(v_inst, 'hidden') = 'hidden' then 'Protected Institution' else a.institution_name end,
      a.provider_name, a.asset_group, a.asset_category, a.asset_subtype, a.source_type,
      -- masked account identifier gated by linked_account_details
      case when coalesce(v_det, 'hidden') in ('limited_detail', 'full_detail') then a.masked_identifier else '••••' end,
      -- ★ THE VALUE: exact ONLY at limited/full; otherwise NULL (raw never leaves)
      case when v_bal in ('limited_detail', 'full_detail') then a.balance_cents else null end,
      a.currency,
      -- holdings only when BOTH balances=full_detail AND linked_account_details=full_detail
      case when v_bal = 'full_detail' and coalesce(v_det, 'hidden') = 'full_detail' then a.holdings else '[]'::jsonb end,
      a.refresh_timestamp, a.last_sync_status, a.confidence_level, a.verification_status, a.created_at,
      v_bal,
      -- The value bracket — ALWAYS coarse, never exact. range_only brackets the per-asset value;
      -- category_summary brackets the per-GROUP total (sum over asset_group, then bracketed) so a
      -- single-asset group can't leak its lone balance. Nothing exact leaves for a non-owner.
      case
        when v_bal = 'range_only'       then public.asset_bracket_low(a.balance_cents)
        -- sum(bigint) returns numeric -> cast back to bigint (asset_bracket_low takes bigint)
        when v_bal = 'category_summary' then public.asset_bracket_low((sum(a.balance_cents) over (partition by a.asset_group))::bigint)
        else null
      end,
      case
        when v_bal = 'range_only'       then public.asset_bracket_high(a.balance_cents)
        when v_bal = 'category_summary' then public.asset_bracket_high((sum(a.balance_cents) over (partition by a.asset_group))::bigint)
        else null
      end
    from public.normalized_assets a
    where a.estate_id = p_estate_id
    order by a.created_at desc;
end;
$function$;


-- ==== db/migrations/0049_20260811_estate_discovery.sql ============================================
-- db/migrations/0049_20260811_estate_discovery.sql
--
-- PHASE 10 — the SERVER-AUTHORITATIVE estate discovery projection.
--
-- The question this answers, for a survivor rather than an owner:
--   "What exists in this estate, what am I allowed to know about it right now,
--    and what is waiting on something before I can know more?"
--
-- ★ THE CLIENT IS NEVER SENT THE ESTATE AND ASKED TO HIDE THINGS. Everything below decides, in the
-- database, what a specific viewer may learn — and returns only that. A category the viewer holds no
-- grant for is not returned as `hidden`; it is not returned AT ALL, because "there is a category here
-- you may not see" is itself a disclosure.
--
-- ★ NO NEW DISCLOSURE VOCABULARY IS INVENTED. `access_grants.visibility_tier` already expresses the
-- ladder (hidden → range_only → category_summary → limited_detail → full_detail) and
-- `release_condition` already expresses "not yet". Phase 10 reuses both. Inventing a parallel
-- level 0..4 enum would have created a second disclosure authority to keep in step with the first.
--
-- ★ MANUAL ASSETS JOIN THE EXISTING GRANT MODEL — WITHOUT TOUCHING ITS SCOPE XOR. Phase 9 refused to
-- add an `asset_id` scope to `access_grants`, because that means altering the document_id/category XOR
-- and the ceiling trigger keyed on it — the security-critical centre of the disclosure model. Instead
-- the manual inventory becomes one more CATEGORY (`estate_inventory`) in a column that already exists
-- and is already ceiling-checked. Three contained edits (CHECK, ceiling fn, the RPC's inline list),
-- no structural change.
--
-- ★ DEATH-BASED RELEASE STAYS DORMANT, DELIBERATELY. `after_verified_death_or_incapacity` remains
-- default-deny exactly as migration 0002 left it. `estate_release_state()` below is the SEAM that a
-- future activation would drive, and it currently reports what the claims machinery already knows —
-- it flips nothing. Death activation is Phase 11 ("Death Activation & Survivor Mode"); wiring it here
-- would be inventing an irreversible disclosure trigger inside a discovery slice.
--
-- Idempotent; safe to re-run.

begin;

-- =============================================================================================
-- 1 · `estate_inventory` becomes a grantable category
-- =============================================================================================
-- The CHECK is rebuilt rather than amended in place — Postgres has no "add a value to a CHECK".
alter table public.access_grants drop constraint if exists access_grants_category_check;
alter table public.access_grants
  add constraint access_grants_category_check
  check (category is null or category in (
    'estate_documents',            -- Vault (0002)
    'account_balances',            -- per-account balance value (0008)
    'institution_names',           -- which institutions are connected (0008)
    'total_asset_value',           -- the estate aggregate net worth (0008)
    'linked_account_details',      -- per-account detail: masked number + holdings (0008)
    'estate_inventory'             -- ★ 0049: the MANUAL asset inventory (estate_assets)
  ));

-- =============================================================================================
-- 2 · the ceiling for the new category
-- =============================================================================================
-- ★ THE BENEFICIARY CAP MATCHES THE MONEY CATEGORIES, ON PURPOSE. A manual asset carries an
-- `approximate_value_cents`, so `estate_inventory` is a $ category in every sense that matters. The
-- established policy is that a beneficiary never receives an exact figure — capping here at
-- `category_summary` keeps one rule for estate value rather than two that will drift.
create or replace function public.asset_category_grantable(p_role text, p_category text, p_tier text)
returns boolean
language sql
immutable
as $$
  select case
    when p_tier = 'hidden' then true
    when p_category in ('account_balances', 'total_asset_value', 'estate_inventory') then
      case p_role
        when 'professional_delegate' then true                          -- up to full_detail
        when 'beneficiary'           then p_tier in ('range_only', 'category_summary')
        else false
      end
    when p_category in ('institution_names', 'linked_account_details') then
      p_role in ('beneficiary', 'professional_delegate')                -- up to full_detail
    else false                                                          -- unknown category -> deny
  end;
$$;

comment on function public.asset_category_grantable(text, text, text) is
  'Asset-disclosure ceiling: max grantable visibility_tier per (role, category). The $ categories — '
  'including estate_inventory (0049) — cap beneficiaries below exact value; professionals may reach '
  'full_detail. THE POLICY KNOB. Mirrors document_grantable for the category path.';

commit;

-- =============================================================================================
-- 3 · RPCs — APPLY db/functions/estate_discovery_rpcs.sql IMMEDIATELY AFTER THIS FILE
-- =============================================================================================
-- The bodies live in ONE place. `scripts/buildEstateDiscoveryBundle.mjs` concatenates this file and
-- that one into a single paste-ready artifact, so the SQL editor still gets one paste.
--
-- NOTE: `create_asset_grant` also carries an INLINE category list which must include
-- `estate_inventory`, or the new category is accepted by the table and rejected by the only door that
-- writes to it. That edit ships in the same functions file, and the authorization suite asserts a
-- grant can actually be created for the new category — a CHECK widened without the door widened would
-- otherwise look correct and be unusable.


-- ==== db/functions/estate_discovery_rpcs.sql ======================================================
-- Estate-discovery RPCs — migration 0049 (Phase 10). Source of truth; re-apply on reset.
--
-- ★ THE WHOLE POINT: the client is never sent the estate and asked to hide things. These functions
-- decide, in the database, what one specific viewer may learn — and return only that.

-- ---------------------------------------------------------------------------------------------
-- create_asset_grant — widen the INLINE category list to admit `estate_inventory`
-- ---------------------------------------------------------------------------------------------
-- ★ A CHECK WIDENED WITHOUT THE DOOR WIDENED IS AN UNUSABLE CATEGORY. `create_asset_grant` carries
-- its own list as defence-in-depth ("the RPC is the security boundary and may be called directly"),
-- so migration 0049's constraint change alone would let the TABLE accept `estate_inventory` while the
-- only door that writes to it kept refusing. Both move together, and the authorization suite asserts
-- a grant can actually be created for the new category.
--
-- Only the list changes. The owner gate, the no-grants-to-owners rule, the write-time ceiling and the
-- unique-violation handling are untouched.
do $$
declare v_src text;
begin
  select pg_get_functiondef(p.oid) into v_src
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'create_asset_grant'
   limit 1;

  if v_src is null then
    raise exception 'create_asset_grant not found — apply migration 0008 first';
  end if;

  -- Idempotent: only rewrite when the new category is absent.
  if position('estate_inventory' in v_src) = 0 then
    v_src := replace(
      v_src,
      $old$('account_balances', 'institution_names', 'total_asset_value', 'linked_account_details')$old$,
      $new$('account_balances', 'institution_names', 'total_asset_value', 'linked_account_details', 'estate_inventory')$new$
    );
    if position('estate_inventory' in v_src) = 0 then
      -- ★ FAIL LOUDLY RATHER THAN SILENTLY NO-OP. If the literal ever changes shape, a quiet
      -- non-replacement would leave the category permanently ungrantable with everything green.
      raise exception 'could not widen create_asset_grant category list — the inline literal changed shape';
    end if;
    execute v_src;
  end if;
end $$;

-- ---------------------------------------------------------------------------------------------
-- estate_release_state(p_estate) -> text   — THE SEAM
-- ---------------------------------------------------------------------------------------------
-- Reports what the CLAIMS machinery already knows about this estate. It flips nothing and grants
-- nothing.
--
-- ★ IT DOES NOT ACTIVATE `after_verified_death_or_incapacity`. That condition stays default-deny
-- exactly as 0002 left it. This function exists so that Phase 11 ("Death Activation & Survivor Mode")
-- has ONE place to drive, instead of a release rule spreading across every read path — and so that
-- the survivor UI can honestly say "a claim is under review" today without any disclosure following
-- from it.
--
-- Values: 'active' (no claim), 'claim_submitted', 'claim_under_review', 'claim_approved',
--         'claim_rejected', 'released'.
create or replace function public.estate_release_state(p_estate uuid)
 returns text
 language sql
 stable
 security definer
 set search_path to 'public'
as $function$
  select coalesce(
    (select case c.status
              when 'submitted'    then 'claim_submitted'
              when 'under_review' then 'claim_under_review'
              when 'approved'     then 'claim_approved'
              when 'released'     then 'released'
              when 'rejected'     then 'claim_rejected'
            end
       from public.claim_packets c
      where c.estate_id = p_estate
      -- The one ACTIVE claim, if any; a rejected row is history and must not mask a later submission.
      order by (c.status <> 'rejected') desc, c.submitted_at desc
      limit 1),
    'active');
$function$;
revoke execute on function public.estate_release_state(uuid) from public, anon;
grant  execute on function public.estate_release_state(uuid) to authenticated;

-- ---------------------------------------------------------------------------------------------
-- inventory_disclosure_tier(p_estate, p_uid) -> text   — the viewer's effective tier
-- ---------------------------------------------------------------------------------------------
-- ★ THE READ-TIME CEILING RE-CHECK IS AUTHORITATIVE, mirroring `list_estate_assets`. A grant created
-- before a ceiling tightening is clamped HERE, so tightening the policy takes effect immediately
-- rather than only for grants issued afterwards.
--
-- ★ RELEASE POLICY IS DECIDED BY THE CANONICAL PREDICATE, never by a local copy of it.
-- `public.release_condition_satisfied` under the `'standard'` policy accepts `immediately`, the two
-- approval-based conditions once approved, and — since Phase 11-D — `after_verified_death` exactly
-- while this estate's AUTHORITATIVE lifecycle is `death_verified` (resolved through
-- `estate_lifecycle_state`, the reader over the record whose only writer is the audited transition
-- routine). It is the identical rule the document path uses, because it is literally the same
-- function. Incapacity-conditioned and legacy fused grants disclose nothing under any lifecycle.
create or replace function public.inventory_disclosure_tier(p_estate uuid, p_uid uuid)
 returns text
 language plpgsql
 stable
 security definer
 set search_path to 'public'
as $function$
declare v_tier text; v_role text; v_cond text; v_approved timestamptz;
begin
  if p_uid is null then return 'hidden'; end if;
  if public.is_estate_owner(p_estate) then return 'full_detail'; end if;

  select g.visibility_tier, g.grantee_role, g.release_condition, g.approved_at
    into v_tier, v_role, v_cond, v_approved
    from public.access_grants g
   where g.estate_id = p_estate
     and g.grantee_user_id = p_uid
     and g.category = 'estate_inventory'
     and g.status = 'active'
   limit 1;

  if v_tier is null then return 'hidden'; end if;

  -- Release gate — the canonical predicate, which is what can_access_document calls too. Since
  -- 11-D it consumes THIS estate's authoritative lifecycle, resolved through the one sanctioned
  -- reader and passed as an ARGUMENT — never compared here: a death-conditioned inventory grant
  -- resolves its tier exactly while the estate is death_verified, and the ceiling clamp below
  -- still has the last word.
  if not public.release_condition_satisfied(v_cond, v_approved, 'standard',
                                            public.estate_lifecycle_state(p_estate)) then
    return 'hidden';
  end if;

  -- Read-time ceiling clamp (authoritative).
  if not public.asset_category_grantable(v_role, 'estate_inventory', v_tier) then
    return 'hidden';
  end if;

  return v_tier;
end;
$function$;
revoke execute on function public.inventory_disclosure_tier(uuid, uuid) from public, anon;
grant  execute on function public.inventory_disclosure_tier(uuid, uuid) to authenticated;

-- ---------------------------------------------------------------------------------------------
-- get_estate_discovery(p_estate) -> jsonb   — THE PROJECTION
-- ---------------------------------------------------------------------------------------------
-- Returns ONLY what this viewer may presently discover.
--
-- Ladder, expressed with the EXISTING `visibility_tier` vocabulary:
--
--   hidden           → nothing. Not "categories: []" with a flag — the estate simply reports no
--                      inventory disclosure, because "there are categories you may not see" is a
--                      disclosure in itself.
--   range_only       → WHICH CATEGORIES EXIST. No counts, no labels, no institutions, no values.
--                      Existence is the disclosure.
--   category_summary → + item counts and a BRACKETED per-category total. Never an exact figure.
--   limited_detail   → + per-item labels and institution names. Still no exact value.
--   full_detail      → + exact values, reference hints and jurisdiction.
--
-- ★ ARCHIVED ASSETS ARE NEVER DISCLOSED TO A NON-OWNER. The owner removed them from the inventory;
-- surfacing them to a survivor would overstate the estate at the worst possible moment.
--
-- ★ NO UUID CROSSES THIS BOUNDARY BELOW `limited_detail`. Even at `limited_detail` the id returned is
-- the asset's own id within an estate the viewer is already authorized for — never a document id,
-- never an estate id belonging to anyone else.
create or replace function public.get_estate_discovery(p_estate uuid)
 returns jsonb
 language plpgsql
 stable
 security definer
 set search_path to 'public'
as $function$
declare
  v_uid       uuid := auth.uid();
  v_tier      text;
  v_is_owner  boolean;
  v_member    boolean;
  v_categories jsonb;
  v_items      jsonb;
  v_docs       int;
begin
  -- ★ UNAUTHENTICATED GETS NOTHING, AND NOT AN ERROR EITHER. An error distinguishes "this estate
  -- exists" from "it does not"; an empty projection does not.
  if v_uid is null then
    return jsonb_build_object('authorized', false);
  end if;

  v_is_owner := public.is_estate_owner(p_estate);
  v_member   := public.is_estate_member(p_estate);

  -- ★ A GRANT ALONE IS ENOUGH — membership is not required. This mirrors the documents precedent: a
  -- grantee may hold a grant before or without an estate_memberships row, and refusing them here
  -- would make the grant unusable. Someone with neither gets the same empty answer as a stranger.
  v_tier := public.inventory_disclosure_tier(p_estate, v_uid);
  if not v_is_owner and not v_member and v_tier = 'hidden' then
    return jsonb_build_object('authorized', false);
  end if;

  -- Documents the viewer can actually reach, counted through the EXISTING document gate rather than
  -- a second rule invented here.
  select count(*) into v_docs
    from public.documents d
   where d.estate_id = p_estate
     and (v_is_owner or public.can_access_document(d.id));

  if v_tier = 'hidden' then
    -- Authorized to be here, but not to discover the inventory. Documents and release state are
    -- still honest answers, and the ABSENCE of a categories key says "not disclosed" without
    -- enumerating what is being withheld.
    return jsonb_build_object(
      'authorized', true,
      'is_owner', v_is_owner,
      'inventory_tier', 'hidden',
      'release_state', public.estate_release_state(p_estate),
      'document_count', v_docs
    );
  end if;

  -- ── categories ───────────────────────────────────────────────────────────────────────────────
  select coalesce(jsonb_agg(x order by x->>'sort_order'), '[]'::jsonb) into v_categories
  from (
    select jsonb_build_object(
             'category',     a.category,
             'display_name', c.display_name,
             'sort_order',   lpad(c.sort_order::text, 4, '0'),
             -- Counts begin at category_summary. At range_only the fact a category EXISTS is the
             -- entire disclosure.
             'item_count',   case when v_tier = 'range_only' then null else count(*) end,
             -- ★ EXACT TOTALS ONLY AT full_detail — AND THIS WAS A REAL LEAK.
             -- This read `v_tier in ('limited_detail','full_detail')`, so `limited_detail` withheld
             -- every per-item `value_cents` and then disclosed the exact CATEGORY TOTAL. For a
             -- category holding one asset the total IS that asset's withheld value, so the tier
             -- leaked precisely what it was suppressing one field away. Found by decoding a captured
             -- payload rather than by reading the code.
             --
             -- limited_detail now brackets, exactly as category_summary does: it adds labels and
             -- institutions over the tier below, and adds NO value precision.
             'total_cents',  case when v_tier = 'full_detail'
                                  then coalesce(sum(a.approximate_value_cents), 0) else null end,
             'range_low_cents',  case when v_tier in ('category_summary','limited_detail')
                                      then public.asset_bracket_low(coalesce(sum(a.approximate_value_cents), 0)::bigint) end,
             'range_high_cents', case when v_tier in ('category_summary','limited_detail')
                                      then public.asset_bracket_high(coalesce(sum(a.approximate_value_cents), 0)::bigint) end
           ) as x
      from public.estate_assets a
      join public.estate_asset_category c on c.value = a.category
     where a.estate_id = p_estate
       and a.archived_at is null
     group by a.category, c.display_name, c.sort_order
  ) s;

  -- ── items ────────────────────────────────────────────────────────────────────────────────────
  -- Nothing per-item below limited_detail.
  if v_tier in ('limited_detail','full_detail') then
    select coalesce(jsonb_agg(jsonb_build_object(
             'id',            a.id,
             'category',      a.category,
             'subtype',       a.subtype,
             'label',         a.label,
             'institution',   a.institution_name,
             'jurisdiction',  case when v_tier = 'full_detail' then a.jurisdiction end,
             'country_code',  case when v_tier = 'full_detail' then a.country_code end,
             -- ★ THE REFERENCE HINT IS full_detail ONLY. It is a fragment of an account identifier;
             -- a survivor who only needs to know an account EXISTS does not need its last four digits.
             'reference_hint', case when v_tier = 'full_detail' then a.reference_hint end,
             'value_cents',   case when v_tier = 'full_detail' then a.approximate_value_cents end,
             'currency',      a.currency,
             'verification_status', a.verification_status,
             'document_count', (select count(*) from public.estate_asset_documents l where l.asset_id = a.id)
           ) order by a.created_at desc), '[]'::jsonb) into v_items
      from public.estate_assets a
     where a.estate_id = p_estate
       and a.archived_at is null;
  else
    v_items := '[]'::jsonb;
  end if;

  return jsonb_build_object(
    'authorized', true,
    'is_owner', v_is_owner,
    'inventory_tier', v_tier,
    'release_state', public.estate_release_state(p_estate),
    'document_count', v_docs,
    'categories', v_categories,
    'items', v_items
  );
end;
$function$;
revoke execute on function public.get_estate_discovery(uuid) from public, anon;
grant  execute on function public.get_estate_discovery(uuid) to authenticated;


-- ==== db/functions/estate_readiness_rpcs.sql ======================================================
-- Estate-readiness RPC — Phase 10-C. Source of truth; re-apply on reset.
--
-- Answers ONE question: **what factual gaps exist in the information the owner has entered into
-- AfterWorth?**
--
-- ★ IT IS NOT A SCORE, A GRADE, A PERCENTAGE OR A HEALTH RATING, AND THE SHAPE MAKES THAT TRUE.
-- There is no numerator, no denominator and no weighting anywhere below — only a list of findings,
-- each naming the object it concerns and the fact that is missing. A score would be a legal-adjacent
-- conclusion this product has no basis to draw: "82% ready" implies someone assessed sufficiency,
-- and nobody did.
--
-- ★ EVERY FINDING IS PROVABLE FROM THE SCHEMA. Nothing here says an insurance policy "needs a
-- beneficiary" — the system holds no authoritative per-asset beneficiary data, so that would be an
-- invented legal requirement dressed as a fact. It says only what the rows can prove: no document is
-- linked, no location is recorded, no value is recorded, sharing is not configured.
--
-- ★ OWNER-ONLY, ENFORCED HERE RATHER THAN BY ROUTING. Readiness is derived from the COMPLETE estate:
-- it counts assets and documents without applying any disclosure tier, because the owner is the one
-- viewer entitled to all of it. That is exactly why a non-owner must never receive it — a readiness
-- list is a census of everything the estate holds, and would reconstruct precisely what
-- `get_estate_discovery` spent Phase 10-A withholding.
--
-- A membership, a professional-delegate role and an executor/trustee designation each confer
-- NOTHING here. 10-D owns the professional workspace and may define its own, differently-scoped
-- projection; it may not reuse this one.

create or replace function public.get_estate_readiness(p_estate uuid)
 returns jsonb
 language plpgsql
 stable
 security definer
 set search_path to 'public'
as $function$
declare
  v_uid      uuid := auth.uid();
  v_findings jsonb;
begin
  -- ★ THE SAME REFUSAL SHAPE AS DISCOVERY, FOR THE SAME REASON. An error would distinguish "this
  -- estate exists but is not yours" from "no such estate"; a bare `authorized:false` does not.
  if v_uid is null then
    return jsonb_build_object('authorized', false);
  end if;
  if not public.is_estate_owner(p_estate) then
    return jsonb_build_object('authorized', false);
  end if;

  select coalesce(jsonb_agg(f order by f->>'sort_key'), '[]'::jsonb) into v_findings
  from (
    -- ── an asset with no supporting evidence ────────────────────────────────────────────────────
    -- The category rides along so the client can word it naturally ("no policy document is linked"
    -- for insurance) WITHOUT the server encoding a legal expectation about what each category
    -- requires. The FACT is identical in every category: nothing is attached.
    select jsonb_build_object(
             'kind',          'missing_evidence',
             'subject_kind',  'asset',
             'subject_id',    a.id,
             'subject_label', a.label,
             'category',      a.category,
             'category_label', c.display_name,
             'sort_key',      '1' || lpad(c.sort_order::text, 4, '0') || a.label
           ) as f
      from public.estate_assets a
      join public.estate_asset_category c on c.value = a.category
     where a.estate_id = p_estate
       -- ★ ARCHIVED ASSETS CONTRIBUTE NOTHING. The owner removed them from the inventory; reporting
       -- a gap on something they deliberately archived would be asking them to fix a record they
       -- have already retired.
       and a.archived_at is null
       and not exists (select 1 from public.estate_asset_documents l where l.asset_id = a.id)

    union all

    -- ── an asset with no location or custodian recorded ─────────────────────────────────────────
    -- A survivor's first question about an account is WHERE it is. This is provable and
    -- jurisdiction-neutral: it states that nothing was recorded, not that anything is required.
    select jsonb_build_object(
             'kind',          'missing_location',
             'subject_kind',  'asset',
             'subject_id',    a.id,
             'subject_label', a.label,
             'category',      a.category,
             'category_label', c.display_name,
             'sort_key',      '2' || lpad(c.sort_order::text, 4, '0') || a.label
           )
      from public.estate_assets a
      join public.estate_asset_category c on c.value = a.category
     where a.estate_id = p_estate
       and a.archived_at is null
       and coalesce(nullif(btrim(a.institution_name), ''), nullif(btrim(a.jurisdiction), ''),
                    nullif(btrim(a.country_code), '')) is null

    union all

    -- ── an asset with no approximate value recorded ─────────────────────────────────────────────
    -- ★ NULL IS THE FINDING, ZERO IS NOT. A recorded zero is a statement the owner made; a null is
    -- the absence of one. Treating them alike would nag an owner about a figure they already gave.
    select jsonb_build_object(
             'kind',          'missing_value',
             'subject_kind',  'asset',
             'subject_id',    a.id,
             'subject_label', a.label,
             'category',      a.category,
             'category_label', c.display_name,
             'sort_key',      '3' || lpad(c.sort_order::text, 4, '0') || a.label
           )
      from public.estate_assets a
      join public.estate_asset_category c on c.value = a.category
     where a.estate_id = p_estate
       and a.archived_at is null
       and a.approximate_value_cents is null

    union all

    -- ── a document whose sharing has never been configured ──────────────────────────────────────
    -- ★ FACTUAL, NOT PRESCRIPTIVE. `sealed` is the level at which `document_grantable` refuses every
    -- role, so "this document cannot currently be shared with anyone" is a property of the data, not
    -- an opinion about what the owner SHOULD do. There is an open product decision about default
    -- sensitivity; this reports the state and takes no position on it, changes nothing, and creates
    -- no grant.
    select jsonb_build_object(
             'kind',          'sharing_not_configured',
             'subject_kind',  'document',
             'subject_id',    d.id,
             'subject_label', d.title,
             'category',      null,
             'category_label', null,
             'sort_key',      '4' || d.title
           )
      from public.documents d
     where d.estate_id = p_estate
       and d.sensitivity = 'sealed'
  ) s;

  return jsonb_build_object(
    'authorized', true,
    'findings', v_findings,
    -- A plain count of the list the OWNER is already holding in full. It is not a score: it has no
    -- denominator, no weighting and no ceiling, and it cannot disclose anything, because every
    -- finding it counts is already in the same payload.
    'finding_count', jsonb_array_length(v_findings)
  );
end;
$function$;
revoke execute on function public.get_estate_readiness(uuid) from public, anon;
grant  execute on function public.get_estate_readiness(uuid) to authenticated;


-- ==== db/functions/professional_workspace_rpcs.sql ================================================
-- Professional-delegate workspace RPC — Phase 10-D. Source of truth; re-apply on reset.
--
-- Answers ONE question, from the delegate's side: **what has the owner of this estate authorized me
-- to see and to do?**
--
-- ★ IT IS NOT READINESS, AND IT MAY NOT BECOME READINESS. `get_estate_readiness` is a census of
-- everything the estate holds, derived WITHOUT applying any disclosure tier, because the owner is the
-- one viewer entitled to all of it. Reusing it here — or reimplementing a "gaps" list from the same
-- tables — would hand a non-owner precisely the reconstruction Phase 10-A spent its whole budget
-- withholding. Nothing below reads an asset or a document except through a gate that already exists.
--
-- ★ IT IS NOT AN OWNER DASHBOARD, AND THE OWNER IS REFUSED. The question this answers is meaningless
-- asked of oneself, and admitting the owner would make "documents shared with me" mean "every
-- document" and "the inventory I was granted" mean "all of it" — two sentences that are true for an
-- owner and false as descriptions of a delegation. The owner already has `get_estate_readiness` and a
-- full-detail `get_estate_discovery`.
--
-- ── AUTHORITY ───────────────────────────────────────────────────────────────────────────────────
--
-- ★ THE GATE IS AN APPROVED `professional_delegate` MEMBERSHIP, READ FROM THE MEMBERSHIP TABLE.
-- It is never inferred from a capability combination, never from the presence of a grant, and never
-- from a fiduciary designation. That direction of inference is what produced the `personaSummary`
-- defect on the client, where an all-false capability set was labelled "Professional delegate"
-- because owner and beneficiary had positive predicates and this role had none.
--
-- ★ A FIDUCIARY DESIGNATION DOES NOT OPEN THIS DOOR, AND MEMBERSHIP DOES NOT CONFER A CAPACITY.
-- An executor who holds no professional-delegate membership is REFUSED here — their surface is the
-- claim path, gated by `is_estate_executor`. A professional delegate who holds no designation
-- receives an EMPTY capacity list, not an absent key, because "we checked and there are none" and
-- "we did not check" are different answers and only one of them is true.
--
-- ★ EVERY DISCLOSURE IS DELEGATED TO THE GATE THAT ALREADY OWNS IT.
--   inventory  → `get_estate_discovery`, unchanged, called as this same caller
--   documents  → `can_access_document`, per document, unchanged
-- Re-deriving either here would create a SECOND disclosure authority, and the first time the two
-- disagreed the more permissive one would be a leak. This function composes; it does not decide.
--
-- ★ NO HIDDEN COUNT CROSSES THIS BOUNDARY. There is no total-minus-visible anywhere, no "documents
-- you cannot see", no count of categories withheld, no denominator. A delegate learns the SIZE of
-- what is being kept from them from exactly one place — a subtraction someone left in a payload — so
-- there is nothing here to subtract from.
--
-- ★ OWNER-DEPENDENCY IS REPORTED AS THE DELEGATE'S OWN STATE, NEVER AS THE ESTATE'S SHAPE.
-- `access_request_state` is the state of a request THIS caller made. It says "you asked and are
-- waiting" — a fact they already hold — and never "3 documents are locked", which would disclose
-- both that documents exist and how many.

create or replace function public.get_professional_workspace(p_estate uuid)
 returns jsonb
 language plpgsql
 stable
 security definer
 set search_path to 'public'
as $function$
declare
  v_uid        uuid := auth.uid();
  v_role       text;
  v_status     text;
  v_name       text;
  v_capacities jsonb;
  v_discovery  jsonb;
  v_docs       jsonb;
  v_doc_count  int;
  v_req_state  text;
  v_req_at     timestamptz;
  v_result     jsonb;
begin
  -- ★ ONE REFUSAL SHAPE, EMITTED BEFORE ANYTHING IS READ. Unauthenticated, non-member, beneficiary,
  -- owner, executor-without-delegation, revoked delegate, cross-estate and no-such-estate must all
  -- produce the IDENTICAL bytes. An error, a differing key set, or a `capacities: []` on one branch
  -- and not another would each turn this into an oracle for "does that estate exist / am I known
  -- there", which is exactly what the discovery refusal was designed to avoid.
  if v_uid is null then
    return jsonb_build_object('authorized', false);
  end if;

  select m.role, m.status
    into v_role, v_status
    from public.estate_memberships m
   where m.estate_id = p_estate
     and m.user_id = v_uid
     -- ★ THE ROLE IS PART OF THE LOOKUP, NOT A POST-FILTER. `estate_memberships` carries no
     -- (estate, user) uniqueness, so a user may hold several rows; selecting on status alone and
     -- checking the role afterwards could pick a beneficiary row and refuse someone who also holds
     -- a professional-delegate one. `list_estate_members` documents the same hazard.
     and m.role = 'professional_delegate'
     and m.status = 'approved'
   limit 1;

  if v_role is null then
    return jsonb_build_object('authorized', false);
  end if;

  -- ★ AND AN OWNER IS REFUSED EVEN IF SOMEONE MANAGES TO HOLD BOTH ROWS. `is_ownership_role` is the
  -- canonical predicate; this is defence in depth against a data state the invariants forbid, and it
  -- costs one boolean. A workspace that quietly served an owner would report "shared with you" over
  -- data nobody shared.
  if public.is_estate_owner(p_estate) then
    return jsonb_build_object('authorized', false);
  end if;

  -- ★ THE COLUMN IS `name`. A first draft wrote `display_name` because that is the spelling the
  -- WIRE uses (`estateDisplayName` in `resolve_membership`), and the two are deliberately different:
  -- the wire name is a presentation contract, the column is storage. Guessing one from the other is
  -- the same class of error as `is_estate_owner` vs the contract's `is_owner` key, which made an
  -- earlier fixture script report every estate as unowned.
  select e.name into v_name from public.estates e where e.id = p_estate;

  -- ── capacity ─────────────────────────────────────────────────────────────────────────────────
  -- ★ FROM DESIGNATIONS ONLY, AND ALWAYS PRESENT. An empty array is the honest answer to "what
  -- capacities do you hold" when the answer is none; omitting the key would make "none" and
  -- "not evaluated" indistinguishable to every client that reads it.
  select coalesce(jsonb_agg(d.designation_type order by d.designation_type), '[]'::jsonb)
    into v_capacities
    from public.estate_designations d
   where d.estate_id = p_estate
     and d.user_id = v_uid
     and d.designation_type in ('executor', 'trustee')
     and d.status = 'active';

  -- ── what the owner released: inventory ───────────────────────────────────────────────────────
  -- Delegated wholesale. Whatever `get_estate_discovery` decides this caller may see is what appears
  -- here, verbatim — including its decision to disclose nothing.
  v_discovery := public.get_estate_discovery(p_estate);

  -- ── what the owner released: documents ───────────────────────────────────────────────────────
  -- ★ THE FILTER IS THE PRODUCT'S OWN DOCUMENT GATE. A document the delegate cannot access is not
  -- counted, not summarised and not alluded to — it is simply not in the result, which is the only
  -- treatment that leaks nothing.
  select coalesce(jsonb_agg(jsonb_build_object('id', d.id, 'title', d.title) order by d.title), '[]'::jsonb),
         count(*)::int
    into v_docs, v_doc_count
    from public.documents d
   where d.estate_id = p_estate
     and public.can_access_document(d.id);

  -- ── what this delegate is waiting on ─────────────────────────────────────────────────────────
  -- ★ THEIR OWN REQUEST, AND NOTHING ELSE. This is a fact the caller supplied; returning it to them
  -- discloses nothing new. There is deliberately no view of anyone else's request, no count of
  -- outstanding requests on the estate, and no statement about what approving one would reveal.
  select r.status, r.created_at
    into v_req_state, v_req_at
    from public.access_requests r
   where r.estate_id = p_estate
     and r.requester_user_id = v_uid
     and r.category = 'estate_documents'
   order by r.created_at desc
   limit 1;

  v_result := jsonb_build_object(
    'authorized',           true,
    'estate_display_name',  v_name,
    -- The relationship, from the membership row that authorized this call. Not a capability
    -- combination, not a label, not a guess.
    'relationship',         v_role,
    'capacities',           v_capacities,
    'document_count',       v_doc_count,
    'documents',            v_docs,
    -- ★ 'none' IS A REAL STATE, NOT A NULL. It means "you have not asked", which the caller can
    -- already see, and it lets the client offer the action without a second round trip.
    'access_request_state', coalesce(v_req_state, 'none'),
    'access_request_at',    v_req_at,
    -- ★ THE ACTION IS OFFERED ONLY WHEN THE SERVER WOULD ACTUALLY HONOUR IT. `create_access_request`
    -- rejects a duplicate pending request with a 409; advertising the action anyway would produce a
    -- CTA whose only outcome is an error, which is worse than no CTA.
    'can_request_document_access', coalesce(v_req_state, 'none') <> 'pending'
  );

  -- ★ INVENTORY IS ADDED ONLY WHEN SOMETHING WAS RELEASED, AND ITS ABSENCE IS THE DISCLOSURE
  -- DECISION ITSELF. Emitting `inventory: null` or `inventory: {categories: []}` would tell the
  -- delegate that an inventory exists and is being withheld — the same distinction
  -- `get_estate_discovery` preserves by omitting `categories` rather than sending an empty array.
  if (v_discovery->>'authorized') = 'true' and (v_discovery->'categories') is not null then
    v_result := v_result || jsonb_build_object(
      'inventory', jsonb_build_object(
        'tier',       v_discovery->>'inventory_tier',
        'categories', v_discovery->'categories',
        'items',      coalesce(v_discovery->'items', '[]'::jsonb)
      )
    );
  end if;

  return v_result;
end;
$function$;

revoke execute on function public.get_professional_workspace(uuid) from public, anon;
grant  execute on function public.get_professional_workspace(uuid) to authenticated;

comment on function public.get_professional_workspace(uuid) is
  'Phase 10-D. The professional delegate''s view of ONE estate: their relationship, any fiduciary '
  'capacity, what the owner released to them (delegated to get_estate_discovery and '
  'can_access_document), and the state of their own access request. Gated on an APPROVED '
  'professional_delegate membership — never on a capability combination, a grant, or a designation. '
  'The owner is refused. Carries no readiness, no score, and no count of anything withheld.';
